DROP PROCEDURE IF EXISTS sp_user_login;
DELIMITER $$

CREATE PROCEDURE sp_user_login(
  IN p_username VARCHAR(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci
)
BEGIN
  SELECT
    u.idUser,
    u.name,
    u.username,
    u.email,
    u.password_hash,
    u.is_active AS user_active,
    u.must_change_password AS mustChangePassword,
    b.idBusiness,
    b.name AS business_name,
    b.slug AS business_slug,
    b.business_type,
    b.logo_url,
    b.is_active AS business_active,
    b.status AS business_status,
    bu.role,
    bu.is_active AS business_user_active
  FROM users u
  INNER JOIN business_users bu ON bu.idUser = u.idUser
  INNER JOIN businesses b ON b.idBusiness = bu.idBusiness
  WHERE u.username = p_username
    AND u.is_active = 1
    AND bu.is_active = 1
    AND b.is_active = 1
  LIMIT 1;
END$$

DELIMITER ;


DROP PROCEDURE IF EXISTS sp_get_authenticated_user_context;
DELIMITER $$

CREATE PROCEDURE sp_get_authenticated_user_context(
  IN p_idUser INT,
  IN p_idBusiness INT
)
BEGIN
  SELECT
    u.idUser,
    b.idBusiness,
    u.name,
    u.username,
    u.email,
    bu.role,
    b.name AS businessName,
    b.slug AS businessSlug,
    b.business_type AS businessType,
    b.logo_url AS logoUrl,
    b.status AS businessStatus,
    u.must_change_password AS mustChangePassword
  FROM users u
  INNER JOIN business_users bu
    ON bu.idUser = u.idUser
    AND bu.idBusiness = p_idBusiness
  INNER JOIN businesses b
    ON b.idBusiness = bu.idBusiness
  WHERE u.idUser = p_idUser
    AND b.idBusiness = p_idBusiness
    AND u.is_active = 1
    AND bu.is_active = 1
    AND b.is_active = 1
  LIMIT 1;
END$$

DELIMITER ;


DROP PROCEDURE IF EXISTS sp_get_user_info_by_id;
DELIMITER $$

CREATE PROCEDURE sp_get_user_info_by_id(
  IN p_idUser INT,
  IN p_idBusiness INT
)
BEGIN
  SELECT
    u.idUser,
    u.name,
    u.username,
    u.email,
    bu.role,
    u.is_active AS isActive,
    u.must_change_password AS mustChangePassword,
    u.created_at AS createdAt
  FROM users u
  INNER JOIN business_users bu
    ON bu.idUser = u.idUser
    AND bu.idBusiness = p_idBusiness
  INNER JOIN businesses b
    ON b.idBusiness = bu.idBusiness
  WHERE u.idUser = p_idUser
    AND bu.idBusiness = p_idBusiness
    AND u.is_active = 1
    AND bu.is_active = 1
    AND b.is_active = 1
  LIMIT 1;
END$$

DELIMITER ;


DROP PROCEDURE IF EXISTS sp_update_user_password;
DELIMITER $$

CREATE PROCEDURE sp_update_user_password(
  IN p_idUser INT,
  IN p_idBusiness INT,
  IN p_newPassword VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci
)
BEGIN
  START TRANSACTION;

  UPDATE users u
  INNER JOIN business_users bu
    ON bu.idUser = u.idUser
    AND bu.idBusiness = p_idBusiness
    AND bu.is_active = 1
  INNER JOIN businesses b
    ON b.idBusiness = bu.idBusiness
    AND b.is_active = 1
  SET
    u.password_hash = p_newPassword,
    u.must_change_password = 0,
    u.updated_at = NOW()
  WHERE u.idUser = p_idUser
    AND u.is_active = 1;

  IF ROW_COUNT() = 0 THEN
    ROLLBACK;
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'Usuario no encontrado o no pertenece al negocio';
  END IF;

  COMMIT;

  SELECT
    p_idUser AS idUser,
    1 AS updated;
END$$

DELIMITER ;


DROP PROCEDURE IF EXISTS sp_create_session;
DELIMITER $$

CREATE PROCEDURE sp_create_session(
  IN p_refresh_token_hash VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  IN p_expires_at DATETIME,
  IN p_user_agent VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  IN p_ip VARCHAR(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  IN p_idUser INT,
  IN p_idBusiness INT
)
BEGIN
  INSERT INTO user_sessions (
    refresh_token_hash,
    created_at,
    expires_at,
    user_agent,
    ip,
    idUser,
    idBusiness
  )
  VALUES (
    p_refresh_token_hash,
    NOW(),
    p_expires_at,
    p_user_agent,
    p_ip,
    p_idUser,
    p_idBusiness
  );

  SELECT LAST_INSERT_ID() AS idLogin;
END$$

DELIMITER ;


DROP PROCEDURE IF EXISTS sp_get_session;
DELIMITER $$

CREATE PROCEDURE sp_get_session(
  IN p_idLogin INT,
  IN p_idUser INT,
  IN p_idBusiness INT
)
BEGIN
  SELECT
    us.idLogin,
    us.refresh_token_hash,
    us.expires_at,
    us.revoked_at,
    us.idUser,
    u.name,
    u.email,
    us.idBusiness,
    bu.role
  FROM user_sessions us
  INNER JOIN users u ON u.idUser = us.idUser
  INNER JOIN business_users bu
    ON bu.idUser = u.idUser
    AND bu.idBusiness = us.idBusiness
  INNER JOIN businesses b ON b.idBusiness = us.idBusiness
  WHERE us.idLogin = p_idLogin
    AND us.idUser = p_idUser
    AND (p_idBusiness IS NULL OR us.idBusiness = p_idBusiness)
    AND us.revoked_at IS NULL
    AND us.expires_at > NOW()
    AND u.is_active = 1
    AND bu.is_active = 1
    AND b.is_active = 1
  LIMIT 1;
END$$

DELIMITER ;



DROP PROCEDURE IF EXISTS sp_revoke_session;
DELIMITER $$

CREATE PROCEDURE sp_revoke_session(
  IN p_idLogin INT
)
BEGIN
  UPDATE user_sessions
  SET revoked_at = NOW()
  WHERE idLogin = p_idLogin
    AND revoked_at IS NULL;
END$$

DELIMITER ;

DROP PROCEDURE IF EXISTS sp_user_register_with_business;
DELIMITER $$

CREATE PROCEDURE sp_user_register_with_business(
  IN p_name VARCHAR(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  IN p_username VARCHAR(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  IN p_email VARCHAR(160) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  IN p_password_hash VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  IN p_business_name VARCHAR(160) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  IN p_business_slug VARCHAR(180) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  IN p_business_type VARCHAR(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  IN p_logoUrl VARCHAR(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  IN p_defaultTrialPlanCode VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  IN p_acceptedTerms TINYINT,
  IN p_acknowledgedPrivacy TINYINT,
  IN p_ipAddress VARCHAR(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  IN p_userAgent VARCHAR(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci
)
BEGIN
  DECLARE v_idUser INT;
  DECLARE v_idBusiness INT;
  DECLARE v_idSubscriptionPlan INT;
  DECLARE v_idBusinessSubscription INT;
  DECLARE v_trialDays INT DEFAULT 0;
  DECLARE v_idTermsVersion BIGINT DEFAULT NULL;
  DECLARE v_idPrivacyVersion BIGINT DEFAULT NULL;

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    RESIGNAL;
  END;

  START TRANSACTION;

  IF p_acceptedTerms <> 1 THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'LEGAL_TERMS_ACCEPTANCE_REQUIRED';
  END IF;

  IF p_acknowledgedPrivacy <> 1 THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'LEGAL_PRIVACY_ACKNOWLEDGEMENT_REQUIRED';
  END IF;

  SET v_idTermsVersion = (
    SELECT v.idLegalDocumentVersion
    FROM legal_documents d
    INNER JOIN legal_document_versions v
      ON v.idLegalDocument = d.idLegalDocument
    WHERE d.code COLLATE utf8mb4_unicode_ci = 'TERMS' COLLATE utf8mb4_unicode_ci
      AND d.is_active = 1
      AND d.required_action = 'ACCEPT'
      AND v.status = 'PUBLISHED'
      AND v.published_at IS NOT NULL
      AND v.published_at <= NOW()
      AND v.effective_at IS NOT NULL
      AND v.effective_at <= NOW()
    ORDER BY v.effective_at DESC, v.idLegalDocumentVersion DESC
    LIMIT 1
  );

  SET v_idPrivacyVersion = (
    SELECT v.idLegalDocumentVersion
    FROM legal_documents d
    INNER JOIN legal_document_versions v
      ON v.idLegalDocument = d.idLegalDocument
    WHERE d.code COLLATE utf8mb4_unicode_ci = 'PRIVACY' COLLATE utf8mb4_unicode_ci
      AND d.is_active = 1
      AND d.required_action = 'ACKNOWLEDGE'
      AND v.status = 'PUBLISHED'
      AND v.published_at IS NOT NULL
      AND v.published_at <= NOW()
      AND v.effective_at IS NOT NULL
      AND v.effective_at <= NOW()
    ORDER BY v.effective_at DESC, v.idLegalDocumentVersion DESC
    LIMIT 1
  );

  IF v_idTermsVersion IS NULL OR v_idPrivacyVersion IS NULL THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'LEGAL_DOCUMENT_NOT_AVAILABLE';
  END IF;

  INSERT INTO users (
    name,
    username,
    email,
    password_hash
  )
  VALUES (
    p_name,
    p_username,
    NULLIF(p_email, ''),
    p_password_hash
  );

  SET v_idUser = LAST_INSERT_ID();

  INSERT INTO businesses (
    name,
    slug,
    logo_url,
    business_type,
    status
  )
  VALUES (
    p_business_name,
    p_business_slug,
    p_logoUrl,
    p_business_type,
    'ACTIVE'
  );

  SET v_idBusiness = LAST_INSERT_ID();

  INSERT INTO business_users (
    idBusiness,
    idUser,
    role
  )
  VALUES (
    v_idBusiness,
    v_idUser,
    'OWNER'
  );

  INSERT INTO legal_acceptances (
    idLegalDocumentVersion,
    idBusiness,
    idUser,
    action_type,
    acceptance_method,
    ip_address,
    user_agent
  )
  VALUES
    (
      v_idTermsVersion,
      v_idBusiness,
      v_idUser,
      'ACCEPTED',
      'REGISTRATION',
      NULLIF(p_ipAddress, ''),
      LEFT(NULLIF(p_userAgent, ''), 500)
    ),
    (
      v_idPrivacyVersion,
      v_idBusiness,
      v_idUser,
      'ACKNOWLEDGED',
      'REGISTRATION',
      NULLIF(p_ipAddress, ''),
      LEFT(NULLIF(p_userAgent, ''), 500)
    );

  INSERT INTO cash_registers (
    idBusiness,
    name,
    description,
    is_default,
    is_active
  )
  VALUES (
    v_idBusiness,
    'Caja principal',
    'Caja creada automaticamente al registrar el negocio',
    1,
    1
  );

  INSERT INTO payment_methods (
    idBusiness,
    code,
    name,
    affects_cash,
    is_default,
    is_active
  )
  VALUES (
    v_idBusiness,
    'CASH',
    'Efectivo',
    1,
    1,
    1
  );

  SELECT idSubscriptionPlan, trial_days
  INTO v_idSubscriptionPlan, v_trialDays
  FROM subscription_plans
  WHERE code COLLATE utf8mb4_unicode_ci = p_defaultTrialPlanCode COLLATE utf8mb4_unicode_ci
    AND is_active = 1
  LIMIT 1;

  IF v_idSubscriptionPlan IS NULL THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'SUBSCRIPTION_PLAN_NOT_FOUND';
  END IF;

  IF v_trialDays <= 0 THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'DEFAULT_TRIAL_PLAN_WITHOUT_TRIAL_DAYS';
  END IF;

  INSERT INTO business_subscriptions (
    idBusiness,
    idSubscriptionPlan,
    status,
    starts_at,
    trial_starts_at,
    trial_ends_at,
    current_period_start,
    current_period_end,
    auto_renew,
    cancel_at_period_end
  )
  VALUES (
    v_idBusiness,
    v_idSubscriptionPlan,
    'TRIAL',
    NOW(),
    NOW(),
    DATE_ADD(NOW(), INTERVAL v_trialDays DAY),
    NULL,
    NULL,
    1,
    0
  );

  SET v_idBusinessSubscription = LAST_INSERT_ID();

  INSERT INTO subscription_events (
    idBusinessSubscription,
    event_type,
    previous_status,
    new_status,
    metadata,
    created_by_user_id
  )
  VALUES (
    v_idBusinessSubscription,
    'TRIAL_STARTED',
    NULL,
    'TRIAL',
    JSON_OBJECT('planCode', p_defaultTrialPlanCode, 'trialDays', v_trialDays),
    v_idUser
  );

  COMMIT;

  SELECT
    v_idUser AS idUser,
    v_idBusiness AS idBusiness,
    p_name AS name,
    p_username AS username,
    NULLIF(p_email, '') AS email,
    p_business_name AS businessName,
    p_business_slug AS businessSlug,
    p_business_type AS businessType,
    p_logoUrl AS logoUrl,
    'ACTIVE' AS businessStatus,
    0 AS mustChangePassword,
    'OWNER' AS role;
END$$

DELIMITER ;

/* ============================================================
   END: procedures/auth.sql
   ============================================================ */

/* ============================================================
   BEGIN: procedures/legal.sql
   ============================================================ */

DELIMITER ;

DROP PROCEDURE IF EXISTS sp_get_current_legal_documents;
DROP PROCEDURE IF EXISTS sp_get_current_legal_document;
DROP PROCEDURE IF EXISTS sp_get_legal_document_version;
DROP PROCEDURE IF EXISTS sp_get_business_user_legal_status;
DROP PROCEDURE IF EXISTS sp_record_legal_acceptance;

DELIMITER $$

CREATE PROCEDURE sp_get_current_legal_documents()
BEGIN
  SELECT
    d.idLegalDocument,
    d.code,
    d.name,
    d.description,
    d.required_action AS requiredAction,
    v.idLegalDocumentVersion,
    v.version,
    v.title,
    v.content_hash AS contentHash,
    v.requires_user_action AS requiresUserAction,
    v.published_at AS publishedAt,
    v.effective_at AS effectiveAt
  FROM legal_documents d
  INNER JOIN legal_document_versions v
    ON v.idLegalDocumentVersion = (
      SELECT v2.idLegalDocumentVersion
      FROM legal_document_versions v2
      WHERE v2.idLegalDocument = d.idLegalDocument
        AND v2.status = 'PUBLISHED'
        AND v2.published_at IS NOT NULL
        AND v2.published_at <= NOW()
        AND v2.effective_at IS NOT NULL
        AND v2.effective_at <= NOW()
      ORDER BY v2.effective_at DESC, v2.idLegalDocumentVersion DESC
      LIMIT 1
    )
  WHERE d.is_active = 1
  ORDER BY d.code;
END$$

CREATE PROCEDURE sp_get_current_legal_document(
  IN p_code VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci
)
BEGIN
  SELECT
    d.idLegalDocument,
    d.code,
    d.name,
    d.description,
    d.required_action AS requiredAction,
    v.idLegalDocumentVersion,
    v.version,
    v.title,
    v.content,
    v.content_hash AS contentHash,
    v.requires_user_action AS requiresUserAction,
    v.published_at AS publishedAt,
    v.effective_at AS effectiveAt
  FROM legal_documents d
  INNER JOIN legal_document_versions v
    ON v.idLegalDocumentVersion = (
      SELECT v2.idLegalDocumentVersion
      FROM legal_document_versions v2
      WHERE v2.idLegalDocument = d.idLegalDocument
        AND v2.status = 'PUBLISHED'
        AND v2.published_at IS NOT NULL
        AND v2.published_at <= NOW()
        AND v2.effective_at IS NOT NULL
        AND v2.effective_at <= NOW()
      ORDER BY v2.effective_at DESC, v2.idLegalDocumentVersion DESC
      LIMIT 1
    )
  WHERE d.is_active = 1
    AND d.code COLLATE utf8mb4_unicode_ci = p_code COLLATE utf8mb4_unicode_ci
  LIMIT 1;
END$$

CREATE PROCEDURE sp_get_legal_document_version(
  IN p_code VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  IN p_version VARCHAR(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci
)
BEGIN
  SELECT
    d.idLegalDocument,
    d.code,
    d.name,
    d.description,
    d.required_action AS requiredAction,
    v.idLegalDocumentVersion,
    v.version,
    v.title,
    v.content,
    v.content_hash AS contentHash,
    v.status,
    v.requires_user_action AS requiresUserAction,
    v.published_at AS publishedAt,
    v.effective_at AS effectiveAt
  FROM legal_documents d
  INNER JOIN legal_document_versions v
    ON v.idLegalDocument = d.idLegalDocument
  WHERE d.code COLLATE utf8mb4_unicode_ci = p_code COLLATE utf8mb4_unicode_ci
    AND v.version COLLATE utf8mb4_unicode_ci = p_version COLLATE utf8mb4_unicode_ci
    AND v.status IN ('PUBLISHED', 'RETIRED')
  LIMIT 1;
END$$

CREATE PROCEDURE sp_get_business_user_legal_status(
  IN p_idBusiness INT,
  IN p_idUser INT
)
BEGIN
  DECLARE v_role VARCHAR(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL;

  SELECT role
  INTO v_role
  FROM business_users
  WHERE idBusiness = p_idBusiness
    AND idUser = p_idUser
    AND is_active = 1
  LIMIT 1;

  SELECT
    d.idLegalDocument,
    d.code,
    d.name,
    d.required_action AS requiredAction,
    cv.idLegalDocumentVersion,
    cv.version AS currentVersion,
    cv.title,
    cv.content_hash AS contentHash,
    cv.requires_user_action AS requiresUserAction,
    cv.effective_at AS effectiveAt,
    CASE
      WHEN d.code COLLATE utf8mb4_unicode_ci = 'TERMS' COLLATE utf8mb4_unicode_ci THEN 'BUSINESS'
      ELSE 'USER'
    END AS acceptanceScope,
    la.idLegalAcceptance,
    la.action_type AS actionType,
    la.acceptance_method AS acceptanceMethod,
    la.accepted_at AS acceptedAt,
    la.idUser AS acceptedByUserId,
    COALESCE(u.name, u.username) AS acceptedByUserName,
    CASE
      WHEN la.idUser = p_idUser THEN 1
      ELSE 0
    END AS acceptedByCurrentUser,
    CASE
      WHEN la.idLegalAcceptance IS NOT NULL THEN 1
      ELSE 0
    END AS isSatisfied,
    CASE
      WHEN cv.idLegalDocumentVersion IS NULL THEN 0
      WHEN d.code COLLATE utf8mb4_unicode_ci = 'TERMS' COLLATE utf8mb4_unicode_ci
        AND la.idLegalAcceptance IS NULL
        AND v_role = 'OWNER' THEN 1
      WHEN d.code COLLATE utf8mb4_unicode_ci = 'PRIVACY' COLLATE utf8mb4_unicode_ci
        AND la.idLegalAcceptance IS NULL THEN 1
      ELSE 0
    END AS actionRequired
  FROM legal_documents d
  LEFT JOIN legal_document_versions cv
    ON cv.idLegalDocumentVersion = (
      SELECT v2.idLegalDocumentVersion
      FROM legal_document_versions v2
      WHERE v2.idLegalDocument = d.idLegalDocument
        AND v2.status = 'PUBLISHED'
        AND v2.published_at IS NOT NULL
        AND v2.published_at <= NOW()
        AND v2.effective_at IS NOT NULL
        AND v2.effective_at <= NOW()
      ORDER BY v2.effective_at DESC, v2.idLegalDocumentVersion DESC
      LIMIT 1
    )
  LEFT JOIN legal_acceptances la
    ON la.idLegalAcceptance = (
      SELECT la2.idLegalAcceptance
      FROM legal_acceptances la2
      WHERE la2.idLegalDocumentVersion = cv.idLegalDocumentVersion
        AND la2.idBusiness = p_idBusiness
        AND (
          (
            d.code COLLATE utf8mb4_unicode_ci = 'TERMS' COLLATE utf8mb4_unicode_ci
            AND la2.action_type = 'ACCEPTED'
          )
          OR (
            d.code COLLATE utf8mb4_unicode_ci = 'PRIVACY' COLLATE utf8mb4_unicode_ci
            AND la2.idUser = p_idUser
            AND la2.action_type = 'ACKNOWLEDGED'
          )
        )
      ORDER BY la2.accepted_at ASC, la2.idLegalAcceptance ASC
      LIMIT 1
    )
  LEFT JOIN users u
    ON u.idUser = la.idUser
  WHERE d.is_active = 1
  ORDER BY d.code;
END$$

CREATE PROCEDURE sp_record_legal_acceptance(
  IN p_idBusiness INT,
  IN p_idUser INT,
  IN p_code VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  IN p_acceptanceMethod VARCHAR(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  IN p_ipAddress VARCHAR(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  IN p_userAgent VARCHAR(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci
)
BEGIN
  DECLARE v_idLegalDocument INT DEFAULT NULL;
  DECLARE v_idLegalDocumentVersion BIGINT DEFAULT NULL;
  DECLARE v_requiredAction VARCHAR(30) DEFAULT NULL;
  DECLARE v_actionType VARCHAR(30) DEFAULT NULL;
  DECLARE v_role VARCHAR(30) DEFAULT NULL;

  SELECT role
  INTO v_role
  FROM business_users
  WHERE idBusiness = p_idBusiness
    AND idUser = p_idUser
    AND is_active = 1
  LIMIT 1;

  IF v_role IS NULL THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'BUSINESS_USER_NOT_FOUND';
  END IF;

  SELECT d.idLegalDocument, d.required_action
  INTO v_idLegalDocument, v_requiredAction
  FROM legal_documents d
  WHERE d.code COLLATE utf8mb4_unicode_ci = p_code COLLATE utf8mb4_unicode_ci
    AND d.is_active = 1
  LIMIT 1;

  IF v_idLegalDocument IS NULL THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'LEGAL_DOCUMENT_NOT_AVAILABLE';
  END IF;

  SELECT v.idLegalDocumentVersion
  INTO v_idLegalDocumentVersion
  FROM legal_document_versions v
  WHERE v.idLegalDocument = v_idLegalDocument
    AND v.status = 'PUBLISHED'
    AND v.published_at IS NOT NULL
    AND v.published_at <= NOW()
    AND v.effective_at IS NOT NULL
    AND v.effective_at <= NOW()
  ORDER BY v.effective_at DESC, v.idLegalDocumentVersion DESC
  LIMIT 1;

  IF v_idLegalDocumentVersion IS NULL THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'LEGAL_DOCUMENT_NOT_AVAILABLE';
  END IF;

  IF p_code COLLATE utf8mb4_unicode_ci = 'TERMS' COLLATE utf8mb4_unicode_ci
    AND v_role <> 'OWNER' THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'LEGAL_TERMS_OWNER_REQUIRED';
  END IF;

  IF v_requiredAction = 'ACCEPT' THEN
    SET v_actionType = 'ACCEPTED';
  ELSEIF v_requiredAction = 'ACKNOWLEDGE' THEN
    SET v_actionType = 'ACKNOWLEDGED';
  ELSE
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'LEGAL_ACTION_NOT_REQUIRED';
  END IF;

  INSERT INTO legal_acceptances (
    idLegalDocumentVersion,
    idBusiness,
    idUser,
    action_type,
    acceptance_method,
    ip_address,
    user_agent
  )
  VALUES (
    v_idLegalDocumentVersion,
    p_idBusiness,
    p_idUser,
    v_actionType,
    p_acceptanceMethod,
    NULLIF(p_ipAddress, ''),
    LEFT(NULLIF(p_userAgent, ''), 500)
  )
  ON DUPLICATE KEY UPDATE
    idLegalAcceptance = LAST_INSERT_ID(idLegalAcceptance);

  SELECT
    la.idLegalAcceptance,
    la.idLegalDocumentVersion,
    d.code,
    d.name,
    v.version,
    la.idBusiness,
    la.idUser,
    la.action_type AS actionType,
    la.acceptance_method AS acceptanceMethod,
    la.accepted_at AS acceptedAt,
    la.ip_address AS ipAddress,
    la.user_agent AS userAgent
  FROM legal_acceptances la
  INNER JOIN legal_document_versions v
    ON v.idLegalDocumentVersion = la.idLegalDocumentVersion
  INNER JOIN legal_documents d
    ON d.idLegalDocument = v.idLegalDocument
  WHERE la.idLegalAcceptance = LAST_INSERT_ID()
  LIMIT 1;
END$$

DELIMITER ;

/* ============================================================
   END: procedures/legal.sql
   ============================================================ */

/* ============================================================
   BEGIN: procedures/platform_auth.sql
   ============================================================ */

ALTER TABLE user_sessions
  MODIFY COLUMN idBusiness INT NULL;

SET @auth_context_exists := (
  SELECT COUNT(*)
  FROM INFORMATION_SCHEMA.COLUMNS
  WHERE TABLE_SCHEMA = DATABASE()
    AND TABLE_NAME = 'user_sessions'
    AND COLUMN_NAME = 'auth_context'
);

SET @auth_context_sql := IF(
  @auth_context_exists = 0,
  'ALTER TABLE user_sessions ADD COLUMN auth_context ENUM(''BUSINESS'', ''PLATFORM'') NOT NULL DEFAULT ''BUSINESS'' AFTER idBusiness',
  'SELECT 1'
);

PREPARE auth_context_stmt FROM @auth_context_sql;
EXECUTE auth_context_stmt;
DEALLOCATE PREPARE auth_context_stmt;

DROP PROCEDURE IF EXISTS sp_platform_user_bootstrap;
DELIMITER $$

CREATE PROCEDURE sp_platform_user_bootstrap(
  IN p_idUser INT,
  IN p_role VARCHAR(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci
)
BEGIN
  DECLARE v_user_exists INT DEFAULT 0;
  DECLARE v_platform_user_exists INT DEFAULT 0;
  DECLARE v_active_super_admins INT DEFAULT 0;
  DECLARE v_lock_acquired INT DEFAULT 0;

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    DO RELEASE_LOCK('maxikiosco_platform_bootstrap');
    RESIGNAL;
  END;

  SELECT GET_LOCK('maxikiosco_platform_bootstrap', 10) INTO v_lock_acquired;

  IF v_lock_acquired <> 1 THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'PLATFORM_BOOTSTRAP_LOCK_TIMEOUT';
  END IF;

  START TRANSACTION;

  SELECT COUNT(*) INTO v_user_exists
  FROM users
  WHERE idUser = p_idUser
    AND is_active = 1;

  IF v_user_exists = 0 THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'USER_NOT_FOUND_OR_INACTIVE';
  END IF;

  SELECT COUNT(*) INTO v_platform_user_exists
  FROM platform_users
  WHERE idUser = p_idUser;

  IF v_platform_user_exists > 0 THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'PLATFORM_USER_ALREADY_EXISTS';
  END IF;

  IF p_role = 'SUPER_ADMIN' THEN
    SELECT COUNT(*) INTO v_active_super_admins
    FROM platform_users
    WHERE role = 'SUPER_ADMIN'
      AND is_active = 1;

    IF v_active_super_admins > 0 THEN
      SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'PLATFORM_ALREADY_BOOTSTRAPPED';
    END IF;
  END IF;

  INSERT INTO platform_users (
    idUser,
    role,
    is_active
  )
  VALUES (
    p_idUser,
    p_role,
    1
  );

  SELECT
    pu.idPlatformUser,
    pu.idUser,
    pu.role,
    pu.is_active AS isActive,
    pu.created_at AS createdAt
  FROM platform_users pu
  WHERE pu.idPlatformUser = LAST_INSERT_ID();

  COMMIT;
  DO RELEASE_LOCK('maxikiosco_platform_bootstrap');
END$$

DELIMITER ;

DROP PROCEDURE IF EXISTS sp_platform_create_base_user;
DELIMITER $$

CREATE PROCEDURE sp_platform_create_base_user(
  IN p_name VARCHAR(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  IN p_username VARCHAR(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  IN p_email VARCHAR(160) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  IN p_password_hash VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci
)
BEGIN
  INSERT INTO users (
    name,
    username,
    email,
    password_hash,
    is_active
  )
  VALUES (
    p_name,
    p_username,
    NULLIF(p_email, ''),
    p_password_hash,
    1
  );

  SELECT
    idUser,
    name,
    username,
    email,
    is_active AS isActive,
    created_at AS createdAt
  FROM users
  WHERE idUser = LAST_INSERT_ID();
END$$

DELIMITER ;

/* ============================================================
   END: procedures/platform_auth.sql
   ============================================================ */

