   BEGIN: procedures/platform_users.sql
   ============================================================ */



DROP PROCEDURE IF EXISTS sp_platform_users_list;
DROP PROCEDURE IF EXISTS sp_platform_users_get_by_id;
DROP PROCEDURE IF EXISTS sp_platform_users_create;
DROP PROCEDURE IF EXISTS sp_platform_users_change_role;
DROP PROCEDURE IF EXISTS sp_platform_users_change_status;
DROP PROCEDURE IF EXISTS sp_platform_users_revoke_sessions;

DELIMITER $$

CREATE PROCEDURE sp_platform_users_list(
  IN p_search VARCHAR(150),
  IN p_role VARCHAR(30),
  IN p_isActive TINYINT,
  IN p_limit INT,
  IN p_offset INT
)
BEGIN
  SELECT
    pu.idPlatformUser,
    u.idUser,
    u.name,
    u.username,
    u.email,
    pu.role,
    pu.is_active AS isActive,
    u.created_at AS createdAt,
    MAX(us.last_used_at) AS lastLoginAt,
    SUM(CASE WHEN us.revoked_at IS NULL AND us.expires_at > NOW() THEN 1 ELSE 0 END) AS activeSessions
  FROM platform_users pu
  INNER JOIN users u ON u.idUser = pu.idUser
  LEFT JOIN user_sessions us ON us.idUser = u.idUser AND us.auth_context = 'PLATFORM'
  WHERE (p_search IS NULL OR p_search = '' OR u.name LIKE CONCAT('%', p_search, '%') OR u.username LIKE CONCAT('%', p_search, '%') OR u.email LIKE CONCAT('%', p_search, '%'))
    AND (p_role IS NULL OR p_role = '' OR pu.role = p_role)
    AND (p_isActive IS NULL OR pu.is_active = p_isActive)
  GROUP BY pu.idPlatformUser, u.idUser, u.name, u.username, u.email, pu.role, pu.is_active, u.created_at
  ORDER BY u.created_at DESC, pu.idPlatformUser DESC
  LIMIT p_limit OFFSET p_offset;

  SELECT COUNT(*) AS totalRecords
  FROM platform_users pu
  INNER JOIN users u ON u.idUser = pu.idUser
  WHERE (p_search IS NULL OR p_search = '' OR u.name LIKE CONCAT('%', p_search, '%') OR u.username LIKE CONCAT('%', p_search, '%') OR u.email LIKE CONCAT('%', p_search, '%'))
    AND (p_role IS NULL OR p_role = '' OR pu.role = p_role)
    AND (p_isActive IS NULL OR pu.is_active = p_isActive);
END$$

CREATE PROCEDURE sp_platform_users_get_by_id(IN p_idPlatformUser INT)
BEGIN
  SELECT
    pu.idPlatformUser,
    u.idUser,
    u.name,
    u.username,
    u.email,
    pu.role,
    pu.is_active AS isActive,
    u.created_at AS createdAt,
    MAX(us.last_used_at) AS lastLoginAt,
    SUM(CASE WHEN us.revoked_at IS NULL AND us.expires_at > NOW() THEN 1 ELSE 0 END) AS activeSessions
  FROM platform_users pu
  INNER JOIN users u ON u.idUser = pu.idUser
  LEFT JOIN user_sessions us ON us.idUser = u.idUser AND us.auth_context = 'PLATFORM'
  WHERE pu.idPlatformUser = p_idPlatformUser
  GROUP BY pu.idPlatformUser, u.idUser, u.name, u.username, u.email, pu.role, pu.is_active, u.created_at
  LIMIT 1;
END$$

CREATE PROCEDURE sp_platform_users_create(
  IN p_name VARCHAR(120),
  IN p_username VARCHAR(120),
  IN p_email VARCHAR(160),
  IN p_passwordHash VARCHAR(255),
  IN p_role VARCHAR(30)
)
BEGIN
  INSERT INTO users (
    name,
    username,
    email,
    password_hash,
    is_active,
    must_change_password
  ) VALUES (
    p_name,
    p_username,
    p_email,
    p_passwordHash,
    1,
    1
  );

  INSERT INTO platform_users (
    idUser,
    role,
    is_active,
    updated_at
  ) VALUES (
    LAST_INSERT_ID(),
    p_role,
    1,
    NOW()
  );

  CALL sp_platform_users_get_by_id(LAST_INSERT_ID());
END$$

CREATE PROCEDURE sp_platform_users_change_role(
  IN p_idPlatformUser INT,
  IN p_role VARCHAR(30)
)
BEGIN
  DECLARE v_currentRole VARCHAR(30);
  DECLARE v_superAdminCount INT DEFAULT 0;

  SELECT role INTO v_currentRole
  FROM platform_users
  WHERE idPlatformUser = p_idPlatformUser
  LIMIT 1;

  IF v_currentRole IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'PLATFORM_USER_NOT_FOUND';
  END IF;

  SELECT COUNT(*) INTO v_superAdminCount
  FROM platform_users
  WHERE role = 'SUPER_ADMIN' AND is_active = 1;

  IF v_currentRole = 'SUPER_ADMIN' AND p_role <> 'SUPER_ADMIN' AND v_superAdminCount <= 1 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'CANNOT_DEMOTE_LAST_SUPER_ADMIN';
  END IF;

  UPDATE platform_users
  SET role = p_role, updated_at = NOW()
  WHERE idPlatformUser = p_idPlatformUser;

  CALL sp_platform_users_get_by_id(p_idPlatformUser);
END$$

CREATE PROCEDURE sp_platform_users_change_status(
  IN p_idPlatformUser INT,
  IN p_isActive TINYINT
)
BEGIN
  DECLARE v_currentRole VARCHAR(30);
  DECLARE v_superAdminCount INT DEFAULT 0;

  SELECT role INTO v_currentRole
  FROM platform_users
  WHERE idPlatformUser = p_idPlatformUser
  LIMIT 1;

  IF v_currentRole IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'PLATFORM_USER_NOT_FOUND';
  END IF;

  SELECT COUNT(*) INTO v_superAdminCount
  FROM platform_users
  WHERE role = 'SUPER_ADMIN' AND is_active = 1;

  IF v_currentRole = 'SUPER_ADMIN' AND p_isActive = 0 AND v_superAdminCount <= 1 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'CANNOT_DEACTIVATE_LAST_SUPER_ADMIN';
  END IF;

  UPDATE platform_users
  SET is_active = p_isActive, updated_at = NOW()
  WHERE idPlatformUser = p_idPlatformUser;

  IF p_isActive = 0 THEN
    UPDATE user_sessions us
    INNER JOIN platform_users pu ON pu.idUser = us.idUser
    SET us.revoked_at = NOW()
    WHERE pu.idPlatformUser = p_idPlatformUser
      AND us.auth_context = 'PLATFORM'
      AND us.revoked_at IS NULL;
  END IF;

  CALL sp_platform_users_get_by_id(p_idPlatformUser);
END$$

CREATE PROCEDURE sp_platform_users_revoke_sessions(
  IN p_idPlatformUser INT,
  IN p_exceptLoginId INT
)
BEGIN
  UPDATE user_sessions us
  INNER JOIN platform_users pu ON pu.idUser = us.idUser
  SET us.revoked_at = NOW()
  WHERE pu.idPlatformUser = p_idPlatformUser
    AND us.auth_context = 'PLATFORM'
    AND us.revoked_at IS NULL
    AND (p_exceptLoginId IS NULL OR us.idLogin <> p_exceptLoginId);

  SELECT ROW_COUNT() AS revokedSessions;
END$$

DELIMITER ;

/* ============================================================
   END: procedures/platform_users.sql
   ============================================================ */

/* ============================================================
   BEGIN: procedures/platform_businesses.sql
   ============================================================ */

DROP PROCEDURE IF EXISTS sp_platform_business_list;
DROP PROCEDURE IF EXISTS sp_platform_business_get_by_id;
DROP PROCEDURE IF EXISTS sp_platform_business_users;
DROP PROCEDURE IF EXISTS sp_platform_business_activity;
DROP PROCEDURE IF EXISTS sp_platform_business_usage;
DROP PROCEDURE IF EXISTS sp_platform_business_recent_sales;
DROP PROCEDURE IF EXISTS sp_platform_business_recent_purchases;
DROP PROCEDURE IF EXISTS sp_platform_business_change_status;
DROP PROCEDURE IF EXISTS sp_platform_business_user_reset_password;

DELIMITER $$

CREATE PROCEDURE sp_platform_business_list(
  IN p_search VARCHAR(150),
  IN p_businessStatus VARCHAR(30),
  IN p_subscriptionStatus VARCHAR(30),
  IN p_planId INT,
  IN p_businessType VARCHAR(100),
  IN p_activityStatus VARCHAR(40),
  IN p_createdFrom DATETIME,
  IN p_createdTo DATETIME,
  IN p_limit INT,
  IN p_offset INT
)
BEGIN
  SELECT
    b.idBusiness,
    b.name,
    b.slug,
    b.logo_url AS logoUrl,
    b.business_type AS businessType,
    b.is_active AS isActive,
    b.status AS businessStatus,
    ownerUser.idUser AS ownerIdUser,
    ownerUser.name AS ownerName,
    ownerUser.username AS ownerUsername,
    ownerUser.email AS ownerEmail,
    bs.idBusinessSubscription,
    sp.name AS planName,
    sp.code AS planCode,
    bs.status AS subscriptionStatus,
    bs.starts_at AS startDate,
    COALESCE(bs.current_period_end, bs.trial_ends_at) AS endDate,
    COALESCE(usageData.activeUsers, 0) AS activeUsers,
    COALESCE(usageData.products, 0) AS products,
    COALESCE(usageData.deposits, 0) AS deposits,
    activityData.lastLoginAt,
    activityData.lastSaleAt,
    activityData.lastPurchaseAt,
    CASE
      WHEN activityData.lastAnyActivityAt IS NULL OR activityData.lastAnyActivityAt = '1000-01-01' THEN 'NEVER_ACTIVATED'
      WHEN activityData.lastAnyActivityAt >= CURDATE() THEN 'ACTIVE_TODAY'
      WHEN activityData.lastAnyActivityAt >= DATE_SUB(NOW(), INTERVAL 7 DAY) THEN 'ACTIVE_7_DAYS'
      WHEN activityData.lastAnyActivityAt >= DATE_SUB(NOW(), INTERVAL 30 DAY) THEN 'ACTIVE_30_DAYS'
      ELSE 'INACTIVE_30_DAYS'
    END AS activityStatus,
    b.created_at AS createdAt
  FROM businesses b
  LEFT JOIN business_users ownerLink
    ON ownerLink.idBusiness = b.idBusiness AND ownerLink.role = 'OWNER'
  LEFT JOIN users ownerUser ON ownerUser.idUser = ownerLink.idUser
  LEFT JOIN business_subscriptions bs
    ON bs.idBusiness = b.idBusiness
    AND bs.idBusinessSubscription = (
      SELECT bs2.idBusinessSubscription
      FROM business_subscriptions bs2
      WHERE bs2.idBusiness = b.idBusiness
      ORDER BY bs2.created_at DESC, bs2.idBusinessSubscription DESC
      LIMIT 1
    )
  LEFT JOIN subscription_plans sp ON sp.idSubscriptionPlan = bs.idSubscriptionPlan
  LEFT JOIN (
    SELECT
      b1.idBusiness,
      (SELECT COUNT(*) FROM business_users bu INNER JOIN users u ON u.idUser = bu.idUser WHERE bu.idBusiness = b1.idBusiness AND bu.is_active = 1 AND u.is_active = 1) AS activeUsers,
      (SELECT COUNT(*) FROM products p WHERE p.idBusiness = b1.idBusiness AND p.is_active = 1) AS products,
      (SELECT COUNT(*) FROM deposits d WHERE d.idBusiness = b1.idBusiness AND d.is_active = 1) AS deposits
    FROM businesses b1
  ) usageData ON usageData.idBusiness = b.idBusiness
  LEFT JOIN (
    SELECT
      b2.idBusiness,
      (SELECT MAX(us.last_used_at) FROM user_sessions us WHERE us.idBusiness = b2.idBusiness AND us.auth_context = 'BUSINESS') AS lastLoginAt,
      (SELECT MAX(s.sale_date) FROM sales s WHERE s.idBusiness = b2.idBusiness) AS lastSaleAt,
      (SELECT MAX(p.purchase_date) FROM purchases p WHERE p.idBusiness = b2.idBusiness) AS lastPurchaseAt,
      GREATEST(
        COALESCE((SELECT MAX(us.last_used_at) FROM user_sessions us WHERE us.idBusiness = b2.idBusiness AND us.auth_context = 'BUSINESS'), '1000-01-01'),
        COALESCE((SELECT MAX(s.sale_date) FROM sales s WHERE s.idBusiness = b2.idBusiness), '1000-01-01'),
        COALESCE((SELECT MAX(p.purchase_date) FROM purchases p WHERE p.idBusiness = b2.idBusiness), '1000-01-01'),
        COALESCE((SELECT MAX(sm.created_at) FROM stock_movements sm WHERE sm.idBusiness = b2.idBusiness), '1000-01-01')
      ) AS lastAnyActivityAt
    FROM businesses b2
  ) activityData ON activityData.idBusiness = b.idBusiness
  WHERE (p_search IS NULL OR p_search = '' OR b.name LIKE CONCAT('%', p_search, '%') OR b.slug LIKE CONCAT('%', p_search, '%') OR ownerUser.email LIKE CONCAT('%', p_search, '%'))
    AND (p_businessStatus IS NULL OR p_businessStatus = '' OR b.status = p_businessStatus)
    AND (p_subscriptionStatus IS NULL OR p_subscriptionStatus = '' OR bs.status = p_subscriptionStatus)
    AND (p_planId IS NULL OR bs.idSubscriptionPlan = p_planId)
    AND (p_businessType IS NULL OR p_businessType = '' OR b.business_type = p_businessType)
    AND (p_createdFrom IS NULL OR b.created_at >= p_createdFrom)
    AND (p_createdTo IS NULL OR b.created_at <= p_createdTo)
    AND (
      p_activityStatus IS NULL OR p_activityStatus = '' OR
      CASE
        WHEN activityData.lastAnyActivityAt IS NULL OR activityData.lastAnyActivityAt = '1000-01-01' THEN 'NEVER_ACTIVATED'
        WHEN activityData.lastAnyActivityAt >= CURDATE() THEN 'ACTIVE_TODAY'
        WHEN activityData.lastAnyActivityAt >= DATE_SUB(NOW(), INTERVAL 7 DAY) THEN 'ACTIVE_7_DAYS'
        WHEN activityData.lastAnyActivityAt >= DATE_SUB(NOW(), INTERVAL 30 DAY) THEN 'ACTIVE_30_DAYS'
        ELSE 'INACTIVE_30_DAYS'
      END = p_activityStatus
    )
  ORDER BY b.created_at DESC, b.idBusiness DESC
  LIMIT p_limit OFFSET p_offset;

  SELECT COUNT(*) AS totalRecords
  FROM businesses b
  LEFT JOIN business_users ownerLink
    ON ownerLink.idBusiness = b.idBusiness AND ownerLink.role = 'OWNER'
  LEFT JOIN users ownerUser ON ownerUser.idUser = ownerLink.idUser
  LEFT JOIN business_subscriptions bs
    ON bs.idBusiness = b.idBusiness
    AND bs.idBusinessSubscription = (
      SELECT bs2.idBusinessSubscription
      FROM business_subscriptions bs2
      WHERE bs2.idBusiness = b.idBusiness
      ORDER BY bs2.created_at DESC, bs2.idBusinessSubscription DESC
      LIMIT 1
    )
  LEFT JOIN (
    SELECT
      b2.idBusiness,
      GREATEST(
        COALESCE((SELECT MAX(us.last_used_at) FROM user_sessions us WHERE us.idBusiness = b2.idBusiness AND us.auth_context = 'BUSINESS'), '1000-01-01'),
        COALESCE((SELECT MAX(s.sale_date) FROM sales s WHERE s.idBusiness = b2.idBusiness), '1000-01-01'),
        COALESCE((SELECT MAX(p.purchase_date) FROM purchases p WHERE p.idBusiness = b2.idBusiness), '1000-01-01'),
        COALESCE((SELECT MAX(sm.created_at) FROM stock_movements sm WHERE sm.idBusiness = b2.idBusiness), '1000-01-01')
      ) AS lastAnyActivityAt
    FROM businesses b2
  ) activityData ON activityData.idBusiness = b.idBusiness
  WHERE (p_search IS NULL OR p_search = '' OR b.name LIKE CONCAT('%', p_search, '%') OR b.slug LIKE CONCAT('%', p_search, '%') OR ownerUser.email LIKE CONCAT('%', p_search, '%'))
    AND (p_businessStatus IS NULL OR p_businessStatus = '' OR b.status = p_businessStatus)
    AND (p_subscriptionStatus IS NULL OR p_subscriptionStatus = '' OR bs.status = p_subscriptionStatus)
    AND (p_planId IS NULL OR bs.idSubscriptionPlan = p_planId)
    AND (p_businessType IS NULL OR p_businessType = '' OR b.business_type = p_businessType)
    AND (p_createdFrom IS NULL OR b.created_at >= p_createdFrom)
    AND (p_createdTo IS NULL OR b.created_at <= p_createdTo)
    AND (
      p_activityStatus IS NULL OR p_activityStatus = '' OR
      CASE
        WHEN activityData.lastAnyActivityAt IS NULL OR activityData.lastAnyActivityAt = '1000-01-01' THEN 'NEVER_ACTIVATED'
        WHEN activityData.lastAnyActivityAt >= CURDATE() THEN 'ACTIVE_TODAY'
        WHEN activityData.lastAnyActivityAt >= DATE_SUB(NOW(), INTERVAL 7 DAY) THEN 'ACTIVE_7_DAYS'
        WHEN activityData.lastAnyActivityAt >= DATE_SUB(NOW(), INTERVAL 30 DAY) THEN 'ACTIVE_30_DAYS'
        ELSE 'INACTIVE_30_DAYS'
      END = p_activityStatus
    );
END$$

CREATE PROCEDURE sp_platform_business_get_by_id(IN p_idBusiness INT)
BEGIN
  SELECT
    b.idBusiness,
    b.name,
    b.slug,
    b.logo_url AS logoUrl,
    b.business_type AS businessType,
    b.is_active AS isActive,
    b.status AS businessStatus,
    b.created_at AS createdAt,
    b.updated_at AS updatedAt,
    ownerUser.idUser AS ownerIdUser,
    ownerUser.name AS ownerName,
    ownerUser.username AS ownerUsername,
    ownerUser.email AS ownerEmail,
    bs.idBusinessSubscription,
    bs.status AS subscriptionStatus,
    bs.starts_at AS startsAt,
    bs.trial_ends_at AS trialEndsAt,
    bs.current_period_start AS currentPeriodStart,
    bs.current_period_end AS currentPeriodEnd,
    bs.auto_renew AS autoRenew,
    sp.idSubscriptionPlan,
    sp.name AS planName,
    sp.code AS planCode,
    sp.billing_period AS billingPeriod,
    sp.max_users AS maxUsers,
    sp.max_products AS maxProducts,
    sp.max_deposits AS maxDeposits
  FROM businesses b
  LEFT JOIN business_users ownerLink
    ON ownerLink.idBusiness = b.idBusiness AND ownerLink.role = 'OWNER'
  LEFT JOIN users ownerUser ON ownerUser.idUser = ownerLink.idUser
  LEFT JOIN business_subscriptions bs
    ON bs.idBusiness = b.idBusiness
    AND bs.idBusinessSubscription = (
      SELECT bs2.idBusinessSubscription
      FROM business_subscriptions bs2
      WHERE bs2.idBusiness = b.idBusiness
      ORDER BY bs2.created_at DESC, bs2.idBusinessSubscription DESC
      LIMIT 1
    )
  LEFT JOIN subscription_plans sp ON sp.idSubscriptionPlan = bs.idSubscriptionPlan
  WHERE b.idBusiness = p_idBusiness
  LIMIT 1;

  CALL sp_platform_business_activity(p_idBusiness);
  CALL sp_platform_business_usage(p_idBusiness);
END$$

CREATE PROCEDURE sp_platform_business_users(IN p_idBusiness INT)
BEGIN
  SELECT
    u.idUser,
    u.name,
    u.username,
    u.email,
    bu.role,
    u.is_active AS userIsActive,
    bu.is_active AS membershipIsActive,
    CASE WHEN u.is_active = 1 AND bu.is_active = 1 THEN 1 ELSE 0 END AS effectiveIsActive,
    u.must_change_password AS mustChangePassword,
    bu.created_at AS createdAt,
    (SELECT MAX(us.last_used_at) FROM user_sessions us WHERE us.idUser = u.idUser AND us.idBusiness = p_idBusiness AND us.auth_context = 'BUSINESS') AS lastLoginAt
  FROM business_users bu
  INNER JOIN users u ON u.idUser = bu.idUser
  WHERE bu.idBusiness = p_idBusiness
  ORDER BY bu.created_at DESC, u.name ASC;
END$$

CREATE PROCEDURE sp_platform_business_activity(IN p_idBusiness INT)
BEGIN
  SELECT
    (SELECT MAX(us.last_used_at) FROM user_sessions us WHERE us.idBusiness = p_idBusiness AND us.auth_context = 'BUSINESS') AS lastLoginAt,
    (SELECT MAX(s.sale_date) FROM sales s WHERE s.idBusiness = p_idBusiness) AS lastSaleAt,
    (SELECT MAX(p.purchase_date) FROM purchases p WHERE p.idBusiness = p_idBusiness) AS lastPurchaseAt,
    (SELECT MAX(sm.created_at) FROM stock_movements sm WHERE sm.idBusiness = p_idBusiness) AS lastStockMovementAt,
    (SELECT COUNT(*) FROM sales s WHERE s.idBusiness = p_idBusiness AND s.sale_date >= CURDATE()) AS salesToday,
    (SELECT COUNT(*) FROM sales s WHERE s.idBusiness = p_idBusiness AND s.sale_date >= DATE_SUB(NOW(), INTERVAL 7 DAY)) AS salesLast7Days,
    (SELECT COUNT(*) FROM sales s WHERE s.idBusiness = p_idBusiness AND s.sale_date >= DATE_SUB(NOW(), INTERVAL 30 DAY)) AS salesLast30Days,
    (SELECT COUNT(*) FROM purchases p WHERE p.idBusiness = p_idBusiness AND p.purchase_date >= DATE_SUB(NOW(), INTERVAL 30 DAY)) AS purchasesLast30Days,
    (SELECT COUNT(*) FROM stock_movements sm WHERE sm.idBusiness = p_idBusiness AND sm.created_at >= DATE_SUB(NOW(), INTERVAL 30 DAY)) AS stockMovementsLast30Days,
    (SELECT COUNT(DISTINCT us.idUser) FROM user_sessions us WHERE us.idBusiness = p_idBusiness AND us.auth_context = 'BUSINESS' AND us.last_used_at >= DATE_SUB(NOW(), INTERVAL 30 DAY)) AS activeUsersLast30Days,
    CASE
      WHEN GREATEST(
        COALESCE((SELECT MAX(us.last_used_at) FROM user_sessions us WHERE us.idBusiness = p_idBusiness AND us.auth_context = 'BUSINESS'), '1000-01-01'),
        COALESCE((SELECT MAX(s.sale_date) FROM sales s WHERE s.idBusiness = p_idBusiness), '1000-01-01'),
        COALESCE((SELECT MAX(p.purchase_date) FROM purchases p WHERE p.idBusiness = p_idBusiness), '1000-01-01'),
        COALESCE((SELECT MAX(sm.created_at) FROM stock_movements sm WHERE sm.idBusiness = p_idBusiness), '1000-01-01')
      ) = '1000-01-01' THEN 'NEVER_ACTIVATED'
      WHEN GREATEST(
        COALESCE((SELECT MAX(us.last_used_at) FROM user_sessions us WHERE us.idBusiness = p_idBusiness AND us.auth_context = 'BUSINESS'), '1000-01-01'),
        COALESCE((SELECT MAX(s.sale_date) FROM sales s WHERE s.idBusiness = p_idBusiness), '1000-01-01'),
        COALESCE((SELECT MAX(p.purchase_date) FROM purchases p WHERE p.idBusiness = p_idBusiness), '1000-01-01'),
        COALESCE((SELECT MAX(sm.created_at) FROM stock_movements sm WHERE sm.idBusiness = p_idBusiness), '1000-01-01')
      ) >= CURDATE() THEN 'ACTIVE_TODAY'
      WHEN GREATEST(
        COALESCE((SELECT MAX(us.last_used_at) FROM user_sessions us WHERE us.idBusiness = p_idBusiness AND us.auth_context = 'BUSINESS'), '1000-01-01'),
        COALESCE((SELECT MAX(s.sale_date) FROM sales s WHERE s.idBusiness = p_idBusiness), '1000-01-01'),
        COALESCE((SELECT MAX(p.purchase_date) FROM purchases p WHERE p.idBusiness = p_idBusiness), '1000-01-01'),
        COALESCE((SELECT MAX(sm.created_at) FROM stock_movements sm WHERE sm.idBusiness = p_idBusiness), '1000-01-01')
      ) >= DATE_SUB(NOW(), INTERVAL 7 DAY) THEN 'ACTIVE_7_DAYS'
      WHEN GREATEST(
        COALESCE((SELECT MAX(us.last_used_at) FROM user_sessions us WHERE us.idBusiness = p_idBusiness AND us.auth_context = 'BUSINESS'), '1000-01-01'),
        COALESCE((SELECT MAX(s.sale_date) FROM sales s WHERE s.idBusiness = p_idBusiness), '1000-01-01'),
        COALESCE((SELECT MAX(p.purchase_date) FROM purchases p WHERE p.idBusiness = p_idBusiness), '1000-01-01'),
        COALESCE((SELECT MAX(sm.created_at) FROM stock_movements sm WHERE sm.idBusiness = p_idBusiness), '1000-01-01')
      ) >= DATE_SUB(NOW(), INTERVAL 30 DAY) THEN 'ACTIVE_30_DAYS'
      ELSE 'INACTIVE_30_DAYS'
    END AS activityStatus;
END$$

CREATE PROCEDURE sp_platform_business_usage(IN p_idBusiness INT)
BEGIN
  SELECT
    (SELECT COUNT(*) FROM business_users bu INNER JOIN users u ON u.idUser = bu.idUser WHERE bu.idBusiness = p_idBusiness AND bu.is_active = 1 AND u.is_active = 1) AS currentUsers,
    sp.max_users AS maxUsers,
    (SELECT COUNT(*) FROM products p WHERE p.idBusiness = p_idBusiness AND p.is_active = 1) AS currentProducts,
    sp.max_products AS maxProducts,
    (SELECT COUNT(*) FROM deposits d WHERE d.idBusiness = p_idBusiness AND d.is_active = 1) AS currentDeposits,
    sp.max_deposits AS maxDeposits,
    CASE WHEN sp.max_products IS NULL OR sp.max_products >= 1000 THEN 1 ELSE 0 END AS bulkImportEnabled
  FROM businesses b
  LEFT JOIN business_subscriptions bs
    ON bs.idBusiness = b.idBusiness
    AND bs.idBusinessSubscription = (
      SELECT bs2.idBusinessSubscription
      FROM business_subscriptions bs2
      WHERE bs2.idBusiness = b.idBusiness
      ORDER BY bs2.created_at DESC, bs2.idBusinessSubscription DESC
      LIMIT 1
    )
  LEFT JOIN subscription_plans sp ON sp.idSubscriptionPlan = bs.idSubscriptionPlan
  WHERE b.idBusiness = p_idBusiness
  LIMIT 1;
END$$

CREATE PROCEDURE sp_platform_business_recent_sales(IN p_idBusiness INT, IN p_limit INT)
BEGIN
  SELECT
    s.idSale,
    s.sale_number AS saleNumber,
    s.sale_date AS saleDate,
    s.total,
    s.status,
    u.name AS userName,
    COALESCE(c.name, 'Consumidor Final') AS customerName
  FROM sales s
  INNER JOIN users u ON u.idUser = s.idUser
  LEFT JOIN customers c ON c.idBusiness = s.idBusiness AND c.idCustomer = s.idCustomer
  WHERE s.idBusiness = p_idBusiness
  ORDER BY s.sale_date DESC, s.idSale DESC
  LIMIT p_limit;
END$$

CREATE PROCEDURE sp_platform_business_recent_purchases(IN p_idBusiness INT, IN p_limit INT)
BEGIN
  SELECT
    p.idPurchase,
    p.purchase_number AS purchaseNumber,
    p.purchase_date AS purchaseDate,
    p.total,
    p.status,
    u.name AS userName,
    s.name AS supplierName
  FROM purchases p
  INNER JOIN users u ON u.idUser = p.idUser
  LEFT JOIN suppliers s ON s.idBusiness = p.idBusiness AND s.idSupplier = p.idSupplier
  WHERE p.idBusiness = p_idBusiness
  ORDER BY p.purchase_date DESC, p.idPurchase DESC
  LIMIT p_limit;
END$$

CREATE PROCEDURE sp_platform_business_change_status(
  IN p_idBusiness INT,
  IN p_isActive TINYINT
)
BEGIN
  DECLARE v_currentActive TINYINT;

  SELECT is_active INTO v_currentActive
  FROM businesses
  WHERE idBusiness = p_idBusiness
  LIMIT 1;

  IF v_currentActive IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'PLATFORM_BUSINESS_NOT_FOUND';
  END IF;

  IF v_currentActive = p_isActive THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'PLATFORM_BUSINESS_STATUS_UNCHANGED';
  END IF;

  UPDATE businesses
  SET
    is_active = p_isActive,
    status = CASE WHEN p_isActive = 1 THEN 'ACTIVE' ELSE 'SUSPENDED' END,
    updated_at = NOW()
  WHERE idBusiness = p_idBusiness;

  IF p_isActive = 0 THEN
    UPDATE user_sessions
    SET revoked_at = NOW()
    WHERE idBusiness = p_idBusiness
      AND auth_context = 'BUSINESS'
      AND revoked_at IS NULL;
  END IF;

  CALL sp_platform_business_get_by_id(p_idBusiness);
END$$

CREATE PROCEDURE sp_platform_business_user_reset_password(
  IN p_idBusiness INT,
  IN p_idUser INT,
  IN p_temporaryPasswordHash VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  IN p_actorPlatformUserId INT
)
BEGIN
  DECLARE v_businessExists INT DEFAULT 0;
  DECLARE v_userExists INT DEFAULT 0;
  DECLARE v_membershipExists INT DEFAULT 0;
  DECLARE v_userIsActive TINYINT DEFAULT 0;
  DECLARE v_membershipIsActive TINYINT DEFAULT 0;
  DECLARE v_platformMembershipExists INT DEFAULT 0;
  DECLARE v_sessionsRevoked INT DEFAULT 0;
  DECLARE v_name VARCHAR(120);
  DECLARE v_username VARCHAR(120);
  DECLARE v_email VARCHAR(160);
  DECLARE v_role VARCHAR(30);

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    RESIGNAL;
  END;

  START TRANSACTION;

  SELECT COUNT(*)
  INTO v_businessExists
  FROM businesses
  WHERE idBusiness = p_idBusiness;

  IF v_businessExists = 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'PLATFORM_BUSINESS_NOT_FOUND';
  END IF;

  SELECT COUNT(*)
  INTO v_userExists
  FROM users
  WHERE idUser = p_idUser;

  IF v_userExists = 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'BUSINESS_USER_NOT_FOUND';
  END IF;

  SELECT COUNT(*)
  INTO v_membershipExists
  FROM business_users bu
  WHERE bu.idBusiness = p_idBusiness
    AND bu.idUser = p_idUser;

  IF v_membershipExists = 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'BUSINESS_USER_NOT_IN_BUSINESS';
  END IF;

  SELECT
    u.is_active,
    bu.is_active,
    bu.role,
    u.name,
    u.username,
    u.email
  INTO
    v_userIsActive,
    v_membershipIsActive,
    v_role,
    v_name,
    v_username,
    v_email
  FROM users u
  INNER JOIN business_users bu
    ON bu.idUser = u.idUser
    AND bu.idBusiness = p_idBusiness
  WHERE u.idUser = p_idUser
  LIMIT 1
  FOR UPDATE;

  IF v_userIsActive = 0 OR v_membershipIsActive = 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'BUSINESS_USER_INACTIVE';
  END IF;

  SELECT COUNT(*)
  INTO v_platformMembershipExists
  FROM platform_users pu
  WHERE pu.idUser = p_idUser
    AND pu.is_active = 1;

  IF v_platformMembershipExists > 0 THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'CANNOT_RESET_PLATFORM_USER_FROM_BUSINESS_FLOW';
  END IF;

  UPDATE users
  SET
    password_hash = p_temporaryPasswordHash,
    must_change_password = 1,
    updated_at = NOW()
  WHERE idUser = p_idUser
    AND is_active = 1;

  IF ROW_COUNT() = 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'BUSINESS_USER_PASSWORD_RESET_FAILED';
  END IF;

  UPDATE user_sessions
  SET revoked_at = NOW()
  WHERE idUser = p_idUser
    AND auth_context = 'BUSINESS'
    AND revoked_at IS NULL;

  SET v_sessionsRevoked = ROW_COUNT();

  COMMIT;

  SELECT
    p_idBusiness AS idBusiness,
    p_idUser AS idUser,
    v_name AS name,
    v_username AS username,
    v_email AS email,
    v_role AS role,
    v_sessionsRevoked AS sessionsRevoked,
    1 AS mustChangePassword;
END$$

DELIMITER ;

/* ============================================================
   END: procedures/platform_businesses.sql
   ============================================================ */

/* ============================================================
   BEGIN: procedures/platform_dashboard.sql
   ============================================================ */


DROP PROCEDURE IF EXISTS sp_platform_dashboard;

DELIMITER $$

CREATE PROCEDURE sp_platform_dashboard()
BEGIN
  SELECT
    COUNT(*) AS total,
    SUM(CASE WHEN is_active = 1 AND status = 'ACTIVE' THEN 1 ELSE 0 END) AS active,
    SUM(CASE WHEN is_active = 0 OR status IN ('SUSPENDED','CANCELLED') THEN 1 ELSE 0 END) AS inactive,
    SUM(CASE WHEN created_at >= DATE_FORMAT(CURDATE(), '%Y-%m-01') THEN 1 ELSE 0 END) AS newThisMonth,
    SUM(CASE
      WHEN created_at >= DATE_FORMAT(DATE_SUB(CURDATE(), INTERVAL 1 MONTH), '%Y-%m-01')
        AND created_at < DATE_FORMAT(CURDATE(), '%Y-%m-01')
      THEN 1 ELSE 0
    END) AS newPreviousMonth
  FROM businesses;

  SELECT
    SUM(CASE WHEN status = 'TRIAL' THEN 1 ELSE 0 END) AS trial,
    SUM(CASE WHEN status = 'ACTIVE' THEN 1 ELSE 0 END) AS active,
    SUM(CASE WHEN status = 'PAST_DUE' THEN 1 ELSE 0 END) AS pastDue,
    SUM(CASE WHEN status = 'SUSPENDED' THEN 1 ELSE 0 END) AS suspended,
    SUM(CASE WHEN status = 'CANCELLED' THEN 1 ELSE 0 END) AS cancelled,
    SUM(CASE WHEN status = 'EXPIRED' THEN 1 ELSE 0 END) AS expired,
    SUM(CASE
      WHEN current_period_end BETWEEN NOW() AND DATE_ADD(NOW(), INTERVAL 7 DAY)
        AND status IN ('TRIAL','ACTIVE','PAST_DUE')
      THEN 1 ELSE 0
    END) AS expiringSoon
  FROM business_subscriptions;

  SELECT
    (
      SELECT COALESCE(SUM(amount), 0)
      FROM subscription_payments
      WHERE status = 'APPROVED'
        AND paid_at >= DATE_FORMAT(CURDATE(), '%Y-%m-01')
    ) AS approvedThisMonth,
    (
      SELECT COALESCE(SUM(amount), 0)
      FROM subscription_payments
      WHERE status = 'APPROVED'
        AND paid_at >= DATE_FORMAT(DATE_SUB(CURDATE(), INTERVAL 1 MONTH), '%Y-%m-01')
        AND paid_at < DATE_FORMAT(CURDATE(), '%Y-%m-01')
    ) AS approvedPreviousMonth,
    (
      SELECT COALESCE(SUM(amount), 0)
      FROM subscription_payments
      WHERE status = 'PENDING'
    ) AS pendingAmount,
    (
      SELECT COALESCE(SUM(amount), 0)
      FROM subscription_payments
      WHERE status = 'REJECTED'
    ) AS rejectedAmount,
    (
      SELECT COALESCE(SUM(sp.price), 0)
      FROM business_subscriptions bs
      INNER JOIN subscription_plans sp ON sp.idSubscriptionPlan = bs.idSubscriptionPlan
      WHERE bs.status = 'ACTIVE' AND sp.billing_period = 'MONTHLY'
    ) AS estimatedMrr;

  SELECT
    (SELECT COUNT(*) FROM sales WHERE status = 'COMPLETED' AND DATE(sale_date) = CURDATE()) AS salesToday,
    (SELECT COUNT(*) FROM sales WHERE status = 'COMPLETED' AND sale_date >= DATE_SUB(NOW(), INTERVAL 7 DAY)) AS salesLast7Days,
    (SELECT COUNT(DISTINCT idBusiness) FROM sales WHERE sale_date >= CURDATE()) AS activeBusinessesToday,
    (SELECT COUNT(DISTINCT idBusiness) FROM sales WHERE sale_date >= DATE_SUB(NOW(), INTERVAL 7 DAY)) AS activeBusinessesLast7Days,
    (
      SELECT COUNT(*)
      FROM businesses b
      LEFT JOIN (
        SELECT idBusiness, MAX(lastActivityAt) AS lastActivityAt
        FROM (
          SELECT idBusiness, MAX(sale_date) AS lastActivityAt FROM sales GROUP BY idBusiness
          UNION ALL
          SELECT idBusiness, MAX(purchase_date) AS lastActivityAt FROM purchases GROUP BY idBusiness
          UNION ALL
          SELECT idBusiness, MAX(created_at) AS lastActivityAt FROM stock_movements GROUP BY idBusiness
        ) activity
        GROUP BY idBusiness
      ) ba ON ba.idBusiness = b.idBusiness
      WHERE ba.lastActivityAt IS NULL OR ba.lastActivityAt < DATE_SUB(NOW(), INTERVAL 30 DAY)
    ) AS inactiveBusinesses30Days,
    (SELECT COUNT(*) FROM business_users bu INNER JOIN users u ON u.idUser = bu.idUser WHERE bu.is_active = 1 AND u.is_active = 1) AS totalBusinessUsers,
    (SELECT COUNT(*) FROM products WHERE is_active = 1) AS totalProducts,
    (SELECT COUNT(*) FROM stock st INNER JOIN products p ON p.idBusiness = st.idBusiness AND p.idProduct = st.idProduct WHERE st.quantity <= p.stock_min) AS criticalStockItems;

  SELECT
    DATE_FORMAT(created_at, '%Y-%m') AS period,
    COUNT(*) AS total
  FROM businesses
  WHERE created_at >= DATE_SUB(DATE_FORMAT(CURDATE(), '%Y-%m-01'), INTERVAL 11 MONTH)
  GROUP BY DATE_FORMAT(created_at, '%Y-%m')
  ORDER BY period;

  SELECT
    DATE_FORMAT(COALESCE(paid_at, created_at), '%Y-%m') AS period,
    COALESCE(SUM(amount), 0) AS amount
  FROM subscription_payments
  WHERE status = 'APPROVED'
    AND COALESCE(paid_at, created_at) >= DATE_SUB(DATE_FORMAT(CURDATE(), '%Y-%m-01'), INTERVAL 11 MONTH)
  GROUP BY DATE_FORMAT(COALESCE(paid_at, created_at), '%Y-%m')
  ORDER BY period;

  SELECT status, COUNT(*) AS total
  FROM business_subscriptions
  GROUP BY status
  ORDER BY status;

  SELECT
    'EXPIRING_SOON' AS type,
    'WARNING' AS severity,
    'Suscripciones por vencer' AS title,
    'Suscripciones con vencimiento dentro de los proximos 7 dias.' AS description,
    COUNT(*) AS total,
    '/platform/subscriptions?section=subscriptions' AS targetUrl
  FROM business_subscriptions
  WHERE current_period_end BETWEEN NOW() AND DATE_ADD(NOW(), INTERVAL 7 DAY)
    AND status IN ('TRIAL','ACTIVE','PAST_DUE')
  UNION ALL
  SELECT
    'PENDING_PAYMENTS',
    'INFO',
    'Pagos pendientes',
    'Pagos SaaS que aun no fueron aprobados.',
    COUNT(*),
    '/platform/subscriptions?section=payments'
  FROM subscription_payments
  WHERE status = 'PENDING'
  UNION ALL
  SELECT
    'REJECTED_PAYMENTS',
    'WARNING',
    'Pagos rechazados',
    'Pagos SaaS rechazados en los ultimos 30 dias.',
    COUNT(*),
    '/platform/subscriptions?section=payments'
  FROM subscription_payments
  WHERE status = 'REJECTED'
    AND created_at >= DATE_SUB(NOW(), INTERVAL 30 DAY)
  UNION ALL
  SELECT
    'INACTIVE_BUSINESSES',
    'CRITICAL',
    'Negocios sin actividad',
    'Negocios sin ventas, compras o movimientos en los ultimos 30 dias.',
    COUNT(*),
    '/platform/businesses'
  FROM businesses b
  LEFT JOIN (
    SELECT idBusiness, MAX(lastActivityAt) AS lastActivityAt
    FROM (
      SELECT idBusiness, MAX(sale_date) AS lastActivityAt FROM sales GROUP BY idBusiness
      UNION ALL
      SELECT idBusiness, MAX(purchase_date) AS lastActivityAt FROM purchases GROUP BY idBusiness
      UNION ALL
      SELECT idBusiness, MAX(created_at) AS lastActivityAt FROM stock_movements GROUP BY idBusiness
    ) activity
    GROUP BY idBusiness
  ) ba ON ba.idBusiness = b.idBusiness
  WHERE ba.lastActivityAt IS NULL OR ba.lastActivityAt < DATE_SUB(NOW(), INTERVAL 30 DAY);
END$$

DELIMITER ;

/* ============================================================
   END: procedures/platform_dashboard.sql
   ============================================================ */

/* ============================================================
   BEGIN: procedures/businesses.sql
   ============================================================ */

DROP PROCEDURE IF EXISTS sp_get_business_by_id;
DELIMITER $$

CREATE PROCEDURE sp_get_business_by_id(
  IN p_idBusiness INT
)
BEGIN
  SELECT
    idBusiness,
    name,
    slug,
    logo_url,
    business_type,
    status,
    is_active,
    created_at,
    updated_at
  FROM businesses
  WHERE idBusiness = p_idBusiness
    AND is_active = 1
  LIMIT 1;
END$$

DELIMITER ;


DROP PROCEDURE IF EXISTS sp_update_business;
DELIMITER $$

CREATE PROCEDURE sp_update_business(
  IN p_idBusiness INT,
  IN p_name VARCHAR(160) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  IN p_slug VARCHAR(180) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  IN p_logo_url VARCHAR(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  IN p_update_logo_url TINYINT,
  IN p_business_type VARCHAR(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci
)
BEGIN
  UPDATE businesses
  SET
    name = COALESCE(p_name, name),
    slug = COALESCE(p_slug, slug),
    logo_url = CASE
      WHEN p_update_logo_url = 1 THEN p_logo_url
      ELSE logo_url
    END,
    business_type = COALESCE(p_business_type, business_type),
    updated_at = NOW()
  WHERE idBusiness = p_idBusiness
    AND is_active = 1;

  SELECT
    idBusiness,
    name,
    slug,
    logo_url,
    business_type,
    status,
    is_active,
    created_at,
    updated_at
  FROM businesses
  WHERE idBusiness = p_idBusiness
    AND is_active = 1
  LIMIT 1;
END$$

DELIMITER ;

/* ============================================================
   END: procedures/businesses.sql
   ============================================================ */

/* ============================================================
   BEGIN: procedures/business_users.sql
   ============================================================ */

DROP PROCEDURE IF EXISTS sp_business_user_list;
DELIMITER $$

CREATE PROCEDURE sp_business_user_list(
  IN p_idBusiness INT,
  IN p_search VARCHAR(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  IN p_role VARCHAR(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  IN p_status VARCHAR(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  IN p_limit INT,
  IN p_offset INT
)
BEGIN
  SELECT
    u.idUser,
    u.name,
    u.username,
    u.email,
    bu.role,
    u.is_active AS userIsActive,
    bu.is_active AS membershipIsActive,
    CASE WHEN u.is_active = 1 AND bu.is_active = 1 THEN 1 ELSE 0 END AS effectiveIsActive,
    u.must_change_password AS mustChangePassword,
    u.created_at AS createdAt,
    u.updated_at AS updatedAt,
    CASE WHEN COUNT(bup.idBusinessUserPermission) > 0 THEN 1 ELSE 0 END AS customizedPermissions
  FROM business_users bu
  INNER JOIN users u ON u.idUser = bu.idUser
  LEFT JOIN business_user_permissions bup
    ON bup.idBusiness = bu.idBusiness
    AND bup.idUser = bu.idUser
  WHERE bu.idBusiness = p_idBusiness
    AND (
      p_search IS NULL
      OR u.name COLLATE utf8mb4_unicode_ci LIKE CONCAT('%', p_search COLLATE utf8mb4_unicode_ci, '%')
      OR u.username COLLATE utf8mb4_unicode_ci LIKE CONCAT('%', p_search COLLATE utf8mb4_unicode_ci, '%')
      OR u.email COLLATE utf8mb4_unicode_ci LIKE CONCAT('%', p_search COLLATE utf8mb4_unicode_ci, '%')
    )
    AND (p_role IS NULL OR bu.role COLLATE utf8mb4_unicode_ci = p_role)
    AND (
      p_status IS NULL
      OR (p_status COLLATE utf8mb4_unicode_ci = 'ACTIVE' AND u.is_active = 1 AND bu.is_active = 1)
      OR (p_status COLLATE utf8mb4_unicode_ci = 'INACTIVE' AND (u.is_active = 0 OR bu.is_active = 0))
    )
  GROUP BY
    u.idUser,
    u.name,
    u.username,
    u.email,
    bu.role,
    u.is_active,
    bu.is_active,
    u.must_change_password,
    u.created_at,
    u.updated_at
  ORDER BY u.created_at DESC, u.idUser DESC
  LIMIT p_limit OFFSET p_offset;

  SELECT COUNT(*) AS totalRecords
  FROM business_users bu
  INNER JOIN users u ON u.idUser = bu.idUser
  WHERE bu.idBusiness = p_idBusiness
    AND (
      p_search IS NULL
      OR u.name COLLATE utf8mb4_unicode_ci LIKE CONCAT('%', p_search COLLATE utf8mb4_unicode_ci, '%')
      OR u.username COLLATE utf8mb4_unicode_ci LIKE CONCAT('%', p_search COLLATE utf8mb4_unicode_ci, '%')
      OR u.email COLLATE utf8mb4_unicode_ci LIKE CONCAT('%', p_search COLLATE utf8mb4_unicode_ci, '%')
    )
    AND (p_role IS NULL OR bu.role COLLATE utf8mb4_unicode_ci = p_role)
    AND (
      p_status IS NULL
      OR (p_status COLLATE utf8mb4_unicode_ci = 'ACTIVE' AND u.is_active = 1 AND bu.is_active = 1)
      OR (p_status COLLATE utf8mb4_unicode_ci = 'INACTIVE' AND (u.is_active = 0 OR bu.is_active = 0))
    );
END$$

DELIMITER ;

DROP PROCEDURE IF EXISTS sp_business_user_get_by_id;
DELIMITER $$

CREATE PROCEDURE sp_business_user_get_by_id(
  IN p_idBusiness INT,
  IN p_idUser INT
)
BEGIN
  SELECT
    u.idUser,
    u.name,
    u.username,
    u.email,
    bu.role,
    u.is_active AS userIsActive,
    bu.is_active AS membershipIsActive,
    CASE WHEN u.is_active = 1 AND bu.is_active = 1 THEN 1 ELSE 0 END AS effectiveIsActive,
    u.must_change_password AS mustChangePassword,
    u.created_at AS createdAt,
    u.updated_at AS updatedAt,
    CASE WHEN COUNT(bup.idBusinessUserPermission) > 0 THEN 1 ELSE 0 END AS customizedPermissions
  FROM business_users bu
  INNER JOIN users u ON u.idUser = bu.idUser
  LEFT JOIN business_user_permissions bup
    ON bup.idBusiness = bu.idBusiness
    AND bup.idUser = bu.idUser
  WHERE bu.idBusiness = p_idBusiness
    AND bu.idUser = p_idUser
  GROUP BY
    u.idUser,
    u.name,
    u.username,
    u.email,
    bu.role,
    u.is_active,
    bu.is_active,
    u.must_change_password,
    u.created_at,
    u.updated_at
  LIMIT 1;
END$$

DELIMITER ;

DROP PROCEDURE IF EXISTS sp_business_user_create;
DELIMITER $$

CREATE PROCEDURE sp_business_user_create(
  IN p_idBusiness INT,
  IN p_name VARCHAR(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  IN p_username VARCHAR(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  IN p_email VARCHAR(160) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  IN p_passwordHash VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  IN p_role VARCHAR(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  IN p_permissions JSON,
  IN p_createdByUserId INT
)
BEGIN
  DECLARE v_idUser INT;
  DECLARE v_permissionsCount INT DEFAULT 0;
  DECLARE v_validPermissionsCount INT DEFAULT 0;

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    RESIGNAL;
  END;

  IF p_role COLLATE utf8mb4_unicode_ci NOT IN ('ADMIN','SELLER','DELIVERY') THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'INVALID_BUSINESS_ROLE';
  END IF;

  START TRANSACTION;

  INSERT INTO users (
    name,
    username,
    email,
    password_hash,
    must_change_password
  )
  VALUES (
    p_name,
    p_username,
    NULLIF(p_email, ''),
    p_passwordHash,
    1
  );

  SET v_idUser = LAST_INSERT_ID();

  INSERT INTO business_users (
    idBusiness,
    idUser,
    role,
    is_active
  )
  VALUES (
    p_idBusiness,
    v_idUser,
    p_role,
    1
  );

  IF p_permissions IS NOT NULL AND JSON_LENGTH(p_permissions) > 0 THEN
    SELECT COUNT(*) INTO v_permissionsCount
    FROM JSON_TABLE(
      p_permissions,
      '$[*]' COLUMNS (
        code VARCHAR(100) PATH '$.code',
        effect VARCHAR(10) PATH '$.effect'
      )
    ) jt;

    SELECT COUNT(*) INTO v_validPermissionsCount
    FROM JSON_TABLE(
      p_permissions,
      '$[*]' COLUMNS (
        code VARCHAR(100) PATH '$.code',
        effect VARCHAR(10) PATH '$.effect'
      )
    ) jt
    INNER JOIN permissions p
      ON p.code COLLATE utf8mb4_unicode_ci = jt.code COLLATE utf8mb4_unicode_ci
      AND p.is_active = 1
    WHERE jt.effect COLLATE utf8mb4_unicode_ci IN ('ALLOW','DENY');

    IF v_permissionsCount <> v_validPermissionsCount THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'INVALID_PERMISSION_CODE';
    END IF;

    INSERT INTO business_user_permissions (
      idBusiness,
      idUser,
      idPermission,
      effect,
      created_by_user_id
    )
    SELECT
      p_idBusiness,
      v_idUser,
      p.idPermission,
      jt.effect,
      p_createdByUserId
    FROM JSON_TABLE(
      p_permissions,
      '$[*]' COLUMNS (
        code VARCHAR(100) PATH '$.code',
        effect VARCHAR(10) PATH '$.effect'
      )
    ) jt
    INNER JOIN permissions p
      ON p.code COLLATE utf8mb4_unicode_ci = jt.code COLLATE utf8mb4_unicode_ci
      AND p.is_active = 1;
  END IF;

  COMMIT;

  CALL sp_business_user_get_by_id(p_idBusiness, v_idUser);
END$$

DELIMITER ;

DROP PROCEDURE IF EXISTS sp_business_user_update;
DELIMITER $$

CREATE PROCEDURE sp_business_user_update(
  IN p_idBusiness INT,
  IN p_idUser INT,
  IN p_name VARCHAR(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  IN p_username VARCHAR(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  IN p_email VARCHAR(160) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci
)
BEGIN
  UPDATE users u
  INNER JOIN business_users bu
    ON bu.idUser = u.idUser
    AND bu.idBusiness = p_idBusiness
  SET
    u.name = p_name,
    u.username = p_username,
    u.email = NULLIF(p_email, ''),
    u.updated_at = NOW()
  WHERE u.idUser = p_idUser
    AND bu.role COLLATE utf8mb4_unicode_ci <> 'OWNER';

  IF ROW_COUNT() = 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'BUSINESS_USER_NOT_FOUND';
  END IF;

  CALL sp_business_user_get_by_id(p_idBusiness, p_idUser);
END$$

DELIMITER ;

DROP PROCEDURE IF EXISTS sp_business_user_change_role;
DELIMITER $$

CREATE PROCEDURE sp_business_user_change_role(
  IN p_idBusiness INT,
  IN p_idUser INT,
  IN p_role VARCHAR(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci
)
BEGIN
  DECLARE v_currentRole VARCHAR(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

  IF p_role COLLATE utf8mb4_unicode_ci NOT IN ('ADMIN','SELLER','DELIVERY') THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'INVALID_BUSINESS_ROLE';
  END IF;

  SELECT role
  INTO v_currentRole
  FROM business_users
  WHERE idBusiness = p_idBusiness
    AND idUser = p_idUser
  LIMIT 1;

  IF v_currentRole IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'BUSINESS_USER_NOT_FOUND';
  END IF;

  IF v_currentRole COLLATE utf8mb4_unicode_ci = 'OWNER' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'CANNOT_MODIFY_OWNER';
  END IF;

  UPDATE business_users
  SET role = p_role
  WHERE idBusiness = p_idBusiness
    AND idUser = p_idUser;

  CALL sp_business_user_get_by_id(p_idBusiness, p_idUser);
END$$

DELIMITER ;

DROP PROCEDURE IF EXISTS sp_business_user_change_status;
DELIMITER $$

CREATE PROCEDURE sp_business_user_change_status(
  IN p_idBusiness INT,
  IN p_idUser INT,
  IN p_actorUserId INT,
  IN p_isActive TINYINT
)
BEGIN
  DECLARE v_role VARCHAR(30);
  DECLARE v_ownerCount INT DEFAULT 0;

  SELECT role INTO v_role
  FROM business_users
  WHERE idBusiness = p_idBusiness
    AND idUser = p_idUser
  LIMIT 1;

  IF v_role IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'BUSINESS_USER_NOT_FOUND';
  END IF;

  IF p_isActive = 0 AND p_idUser = p_actorUserId THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'CANNOT_DEACTIVATE_SELF';
  END IF;

  IF p_isActive = 0 AND v_role COLLATE utf8mb4_unicode_ci = 'OWNER' THEN
    SELECT COUNT(*) INTO v_ownerCount
    FROM business_users bu
    INNER JOIN users u ON u.idUser = bu.idUser
    WHERE bu.idBusiness = p_idBusiness
      AND bu.role COLLATE utf8mb4_unicode_ci = 'OWNER'
      AND bu.is_active = 1
      AND u.is_active = 1;

    IF v_ownerCount <= 1 THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'CANNOT_DEACTIVATE_LAST_OWNER';
    END IF;
  END IF;

  START TRANSACTION;

  UPDATE business_users
  SET is_active = p_isActive
  WHERE idBusiness = p_idBusiness
    AND idUser = p_idUser;

  IF p_isActive = 0 THEN
    UPDATE user_sessions
    SET revoked_at = NOW()
    WHERE idBusiness = p_idBusiness
      AND idUser = p_idUser
      AND revoked_at IS NULL;
  END IF;

  COMMIT;

  CALL sp_business_user_get_by_id(p_idBusiness, p_idUser);
END$$

DELIMITER ;

DROP PROCEDURE IF EXISTS sp_permission_catalog;
DELIMITER $$

CREATE PROCEDURE sp_permission_catalog()
BEGIN
  SELECT
    idPermission,
    code,
    module,
    action,
    name,
    description,
    is_active AS isActive
  FROM permissions
  WHERE is_active = 1
  ORDER BY module ASC, action ASC, code ASC;
END$$

DELIMITER ;

DROP PROCEDURE IF EXISTS sp_business_user_role_permissions;
DELIMITER $$

CREATE PROCEDURE sp_business_user_role_permissions(
  IN p_role VARCHAR(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci
)
BEGIN
  IF p_role COLLATE utf8mb4_unicode_ci = 'OWNER' THEN
    SELECT code
    FROM permissions
    WHERE is_active = 1
    ORDER BY code ASC;
  ELSE
    SELECT p.code
    FROM role_permissions rp
    INNER JOIN permissions p ON p.idPermission = rp.idPermission
    WHERE rp.role COLLATE utf8mb4_unicode_ci = p_role
      AND p.is_active = 1
    ORDER BY p.code ASC;
  END IF;
END$$

DELIMITER ;

DROP PROCEDURE IF EXISTS sp_business_user_permission_overrides;
DELIMITER $$

CREATE PROCEDURE sp_business_user_permission_overrides(
  IN p_idBusiness INT,
  IN p_idUser INT
)
BEGIN
  SELECT
    p.code,
    p.module,
    p.action,
    p.name,
    bup.effect
  FROM business_user_permissions bup
  INNER JOIN permissions p ON p.idPermission = bup.idPermission
  INNER JOIN business_users bu
    ON bu.idBusiness = bup.idBusiness
    AND bu.idUser = bup.idUser
  WHERE bup.idBusiness = p_idBusiness
    AND bup.idUser = p_idUser
    AND p.is_active = 1
  ORDER BY p.module ASC, p.action ASC, p.code ASC;
END$$

DELIMITER ;

DROP PROCEDURE IF EXISTS sp_business_user_set_permission_overrides;
DELIMITER $$

CREATE PROCEDURE sp_business_user_set_permission_overrides(
  IN p_idBusiness INT,
  IN p_idUser INT,
  IN p_permissions JSON,
  IN p_actorUserId INT
)
BEGIN
  DECLARE v_role VARCHAR(30);
  DECLARE v_permissionsCount INT DEFAULT 0;
  DECLARE v_validPermissionsCount INT DEFAULT 0;

  SELECT role INTO v_role
  FROM business_users
  WHERE idBusiness = p_idBusiness
    AND idUser = p_idUser
  LIMIT 1;

  IF v_role IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'BUSINESS_USER_NOT_FOUND';
  END IF;

  IF v_role COLLATE utf8mb4_unicode_ci = 'OWNER' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'CANNOT_MODIFY_OWNER';
  END IF;

  IF p_permissions IS NOT NULL AND JSON_LENGTH(p_permissions) > 0 THEN
    SELECT COUNT(*) INTO v_permissionsCount
    FROM JSON_TABLE(
      p_permissions,
      '$[*]' COLUMNS (
        code VARCHAR(100) PATH '$.code',
        effect VARCHAR(10) PATH '$.effect'
      )
    ) jt;

    SELECT COUNT(*) INTO v_validPermissionsCount
    FROM JSON_TABLE(
      p_permissions,
      '$[*]' COLUMNS (
        code VARCHAR(100) PATH '$.code',
        effect VARCHAR(10) PATH '$.effect'
      )
    ) jt
    INNER JOIN permissions p
      ON p.code COLLATE utf8mb4_unicode_ci = jt.code COLLATE utf8mb4_unicode_ci
      AND p.is_active = 1
    WHERE jt.effect COLLATE utf8mb4_unicode_ci IN ('ALLOW','DENY');

    IF v_permissionsCount <> v_validPermissionsCount THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'INVALID_PERMISSION_CODE';
    END IF;
  END IF;

  START TRANSACTION;

  DELETE FROM business_user_permissions
  WHERE idBusiness = p_idBusiness
    AND idUser = p_idUser;

  IF p_permissions IS NOT NULL AND JSON_LENGTH(p_permissions) > 0 THEN
    INSERT INTO business_user_permissions (
      idBusiness,
      idUser,
      idPermission,
      effect,
      created_by_user_id
    )
    SELECT
      p_idBusiness,
      p_idUser,
      p.idPermission,
      jt.effect,
      p_actorUserId
    FROM JSON_TABLE(
      p_permissions,
      '$[*]' COLUMNS (
        code VARCHAR(100) PATH '$.code',
        effect VARCHAR(10) PATH '$.effect'
      )
    ) jt
    INNER JOIN permissions p
      ON p.code COLLATE utf8mb4_unicode_ci = jt.code COLLATE utf8mb4_unicode_ci
      AND p.is_active = 1;
  END IF;

  COMMIT;

  CALL sp_business_user_permission_overrides(p_idBusiness, p_idUser);
END$$

DELIMITER ;

DROP PROCEDURE IF EXISTS sp_business_user_reset_permission_overrides;
DELIMITER $$

CREATE PROCEDURE sp_business_user_reset_permission_overrides(
  IN p_idBusiness INT,
  IN p_idUser INT
)
BEGIN
  DECLARE v_role VARCHAR(30);

  SELECT role INTO v_role
  FROM business_users
  WHERE idBusiness = p_idBusiness
    AND idUser = p_idUser
  LIMIT 1;

  IF v_role IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'BUSINESS_USER_NOT_FOUND';
  END IF;

  IF v_role COLLATE utf8mb4_unicode_ci = 'OWNER' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'CANNOT_MODIFY_OWNER';
  END IF;

  DELETE FROM business_user_permissions
  WHERE idBusiness = p_idBusiness
    AND idUser = p_idUser;
END$$

DELIMITER ;

DROP PROCEDURE IF EXISTS sp_business_user_effective_permissions;
DELIMITER $$

CREATE PROCEDURE sp_business_user_effective_permissions(
  IN p_idBusiness INT,
  IN p_idUser INT
)
BEGIN
  DECLARE v_role VARCHAR(30);

  SELECT bu.role INTO v_role
  FROM business_users bu
  INNER JOIN users u ON u.idUser = bu.idUser
  WHERE bu.idBusiness = p_idBusiness
    AND bu.idUser = p_idUser
    AND bu.is_active = 1
    AND u.is_active = 1
  LIMIT 1;

  IF v_role IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'BUSINESS_USER_NOT_FOUND';
  END IF;

  IF v_role COLLATE utf8mb4_unicode_ci = 'OWNER' THEN
    SELECT code
    FROM permissions
    WHERE is_active = 1
    ORDER BY code ASC;
  ELSE
    SELECT DISTINCT effective.code
    FROM (
      SELECT p.code
      FROM role_permissions rp
      INNER JOIN permissions p ON p.idPermission = rp.idPermission
      LEFT JOIN business_user_permissions denyOverride
        ON denyOverride.idBusiness = p_idBusiness
        AND denyOverride.idUser = p_idUser
        AND denyOverride.idPermission = p.idPermission
        AND denyOverride.effect COLLATE utf8mb4_unicode_ci = 'DENY'
      WHERE rp.role COLLATE utf8mb4_unicode_ci = v_role COLLATE utf8mb4_unicode_ci
        AND p.is_active = 1
        AND denyOverride.idBusinessUserPermission IS NULL

      UNION

      SELECT p.code
      FROM business_user_permissions allowOverride
      INNER JOIN permissions p ON p.idPermission = allowOverride.idPermission
      WHERE allowOverride.idBusiness = p_idBusiness
        AND allowOverride.idUser = p_idUser
        AND allowOverride.effect COLLATE utf8mb4_unicode_ci = 'ALLOW'
        AND p.is_active = 1
    ) effective
    ORDER BY effective.code ASC;
  END IF;
END$$

DELIMITER ;

/* ============================================================
