  IN p_severity VARCHAR(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  IN p_type VARCHAR(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
