DROP PROCEDURE IF EXISTS sp_create_initial_stock;
DELIMITER $$

CREATE PROCEDURE sp_create_initial_stock(
  IN p_idBusiness INT,
  IN p_idUser INT,
  IN p_idProduct INT,
  IN p_idDeposit INT,
  IN p_quantity DECIMAL(18,2),
  IN p_observation VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci
)
BEGIN
  DECLARE v_idStock INT;
  DECLARE v_idMovement INT;
  DECLARE v_unit_type VARCHAR(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    RESIGNAL;
  END;

  IF EXISTS (
    SELECT 1
    FROM stock
    WHERE idBusiness = p_idBusiness
      AND idProduct = p_idProduct
      AND idDeposit = p_idDeposit
  ) THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'El producto ya se encuentra registrado en este deposito. Realice un ajuste de stock.';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM products
    WHERE idBusiness = p_idBusiness
      AND idProduct = p_idProduct
  ) THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'El producto indicado no existe o no pertenece al negocio';
  END IF;

  SELECT unit_type
  INTO v_unit_type
  FROM products
  WHERE idBusiness = p_idBusiness
    AND idProduct = p_idProduct
  LIMIT 1;

  IF p_quantity IS NULL OR p_quantity < 0 THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'La cantidad inicial no puede ser negativa';
  END IF;

  IF v_unit_type = 'UNIT' AND p_quantity <> FLOOR(p_quantity) THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'Los productos por unidad solo permiten cantidades enteras';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM deposits
    WHERE idBusiness = p_idBusiness
      AND idDeposit = p_idDeposit
      AND is_active = 1
  ) THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'El deposito indicado no existe o no pertenece al negocio';
  END IF;

  START TRANSACTION;

  INSERT INTO stock (
    idBusiness,
    idProduct,
    idDeposit,
    quantity,
    updated_at
  )
  VALUES (
    p_idBusiness,
    p_idProduct,
    p_idDeposit,
    p_quantity,
    NOW()
  );

  SET v_idStock = LAST_INSERT_ID();

  IF p_quantity > 0 THEN
    INSERT INTO stock_movements (
      idBusiness,
      idProduct,
      idUser,
      movement_type,
      idDepositFrom,
      idDepositTo,
      quantity,
      reference_type,
      reference_id,
      observation,
      created_at
    )
    VALUES (
      p_idBusiness,
      p_idProduct,
      p_idUser,
      'ADJUSTMENT_IN',
      NULL,
      p_idDeposit,
      p_quantity,
      'ADJUSTMENT',
      NULL,
      p_observation,
      NOW()
    );

    SET v_idMovement = LAST_INSERT_ID();

    UPDATE stock_movements
    SET reference_id = v_idMovement
    WHERE idStockMovement = v_idMovement;
  END IF;

  COMMIT;

  CALL sp_get_stock_by_id(p_idBusiness, v_idStock);
END$$

DELIMITER ;


DROP PROCEDURE IF EXISTS sp_get_advanced_stock_inventory;
DELIMITER $$

CREATE PROCEDURE sp_get_advanced_stock_inventory(
  IN p_idBusiness INT,
  IN p_search VARCHAR(160) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  IN p_idDeposit INT,
  IN p_quantity DECIMAL(18,2),
  IN p_minQuantity DECIMAL(18,2),
  IN p_maxQuantity DECIMAL(18,2),
  IN p_alertStatus VARCHAR(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  IN p_limit INT,
  IN p_offset INT
)
BEGIN
  SELECT
    s.idStock,
    s.idProduct,
    p.name AS productName,
    pc.name AS categoryName,
    p.barcode,
    p.image_url AS imageUrl,
    p.unit_type AS unitType,
    p.is_active AS isActive,
    p.price_cost AS priceCost,
    p.price_sale AS priceSale,
    s.idDeposit,
    d.name AS depositName,
    s.quantity,
    p.stock_min AS stockMin,
    CASE
      WHEN s.quantity = 0 THEN 'ZERO'
      WHEN s.quantity > 0 AND s.quantity <= p.stock_min THEN 'LOW'
      ELSE 'OK'
    END AS alertStatus
  FROM stock s
  INNER JOIN products p
    ON p.idProduct = s.idProduct
    AND p.idBusiness = s.idBusiness
  INNER JOIN deposits d
    ON d.idDeposit = s.idDeposit
    AND d.idBusiness = s.idBusiness
  LEFT JOIN product_categories pc
    ON pc.idProductCategory = p.idProductCategory
    AND pc.idBusiness = p.idBusiness
  WHERE s.idBusiness = p_idBusiness
    AND (
      p_search IS NULL
      OR p_search = ''
      OR p.name COLLATE utf8mb4_unicode_ci LIKE CONCAT('%', p_search COLLATE utf8mb4_unicode_ci, '%')
      OR p.barcode COLLATE utf8mb4_unicode_ci LIKE CONCAT('%', p_search COLLATE utf8mb4_unicode_ci, '%')
    )
    AND (p_idDeposit IS NULL OR s.idDeposit = p_idDeposit)
    AND (p_quantity IS NULL OR s.quantity = p_quantity)
    AND (p_minQuantity IS NULL OR s.quantity >= p_minQuantity)
    AND (p_maxQuantity IS NULL OR s.quantity <= p_maxQuantity)
    AND (
      p_alertStatus IS NULL
      OR p_alertStatus = ''
      OR (
        CASE
          WHEN s.quantity = 0 THEN 'ZERO'
          WHEN s.quantity > 0 AND s.quantity <= p.stock_min THEN 'LOW'
          ELSE 'OK'
        END
      ) COLLATE utf8mb4_unicode_ci = p_alertStatus COLLATE utf8mb4_unicode_ci
    )
  ORDER BY p.name ASC, d.name ASC, s.idStock ASC
  LIMIT p_limit OFFSET p_offset;

  SELECT
    COUNT(*) AS totalRecords
  FROM stock s
  INNER JOIN products p
    ON p.idProduct = s.idProduct
    AND p.idBusiness = s.idBusiness
  INNER JOIN deposits d
    ON d.idDeposit = s.idDeposit
    AND d.idBusiness = s.idBusiness
  LEFT JOIN product_categories pc
    ON pc.idProductCategory = p.idProductCategory
    AND pc.idBusiness = p.idBusiness
  WHERE s.idBusiness = p_idBusiness
    AND (
      p_search IS NULL
      OR p_search = ''
      OR p.name COLLATE utf8mb4_unicode_ci LIKE CONCAT('%', p_search COLLATE utf8mb4_unicode_ci, '%')
      OR p.barcode COLLATE utf8mb4_unicode_ci LIKE CONCAT('%', p_search COLLATE utf8mb4_unicode_ci, '%')
    )
    AND (p_idDeposit IS NULL OR s.idDeposit = p_idDeposit)
    AND (p_quantity IS NULL OR s.quantity = p_quantity)
    AND (p_minQuantity IS NULL OR s.quantity >= p_minQuantity)
    AND (p_maxQuantity IS NULL OR s.quantity <= p_maxQuantity)
    AND (
      p_alertStatus IS NULL
      OR p_alertStatus = ''
      OR (
        CASE
          WHEN s.quantity = 0 THEN 'ZERO'
          WHEN s.quantity > 0 AND s.quantity <= p.stock_min THEN 'LOW'
          ELSE 'OK'
        END
      ) COLLATE utf8mb4_unicode_ci = p_alertStatus COLLATE utf8mb4_unicode_ci
    );
END$$

DELIMITER ;


DROP PROCEDURE IF EXISTS sp_get_stock;
DELIMITER $$

CREATE PROCEDURE sp_get_stock(
  IN p_idBusiness INT,
  IN p_limit INT,
  IN p_offset INT
)
BEGIN
  SELECT
    s.idStock,
    s.idBusiness,
    b.name AS business_name,
    s.idProduct,
    p.name AS product_name,
    p.image_url AS product_image_url,
    p.unit_type AS product_unit_type,
    p.is_active,
    pc.name AS category_name,
    s.idDeposit,
    d.name AS deposit_name,
    s.quantity,
    s.updated_at,
    p.stock_min
  FROM stock s
  INNER JOIN businesses b ON b.idBusiness = s.idBusiness
  INNER JOIN products p
    ON p.idProduct = s.idProduct
    AND p.idBusiness = s.idBusiness
  INNER JOIN deposits d
    ON d.idDeposit = s.idDeposit
    AND d.idBusiness = s.idBusiness
  INNER JOIN product_categories pc
    ON p.idProductCategory = pc.idProductCategory
    AND pc.idBusiness = s.idBusiness
  WHERE s.idBusiness = p_idBusiness
  ORDER BY p.name ASC, d.name ASC, s.idStock ASC
  LIMIT p_limit OFFSET p_offset;

  SELECT
    COUNT(*) AS totalRecords
  FROM stock s
  INNER JOIN products p
    ON p.idProduct = s.idProduct
    AND p.idBusiness = s.idBusiness
  INNER JOIN deposits d
    ON d.idDeposit = s.idDeposit
    AND d.idBusiness = s.idBusiness
  INNER JOIN product_categories pc
    ON p.idProductCategory = pc.idProductCategory
    AND pc.idBusiness = s.idBusiness
  WHERE s.idBusiness = p_idBusiness;
END$$

DELIMITER ;


DROP PROCEDURE IF EXISTS sp_get_stock_by_id;
DELIMITER $$

CREATE PROCEDURE sp_get_stock_by_id(
  IN p_idBusiness INT,
  IN p_idStock INT
)
BEGIN
  SELECT
    s.idStock,
    s.idBusiness,
    b.name AS business_name,
    s.idProduct,
    p.name AS product_name,
    p.image_url AS product_image_url,
    p.unit_type AS product_unit_type,
    p.is_active,
    pc.name AS category_name,
    s.idDeposit,
    d.name AS deposit_name,
    s.quantity,
    s.updated_at,
    p.stock_min
  FROM stock s
  INNER JOIN businesses b ON b.idBusiness = s.idBusiness
  INNER JOIN products p
    ON p.idProduct = s.idProduct
    AND p.idBusiness = s.idBusiness
  INNER JOIN deposits d
    ON d.idDeposit = s.idDeposit
    AND d.idBusiness = s.idBusiness
  INNER JOIN product_categories pc
    ON p.idProductCategory = pc.idProductCategory
  WHERE s.idBusiness = p_idBusiness
    AND s.idStock = p_idStock
  LIMIT 1;
END$$

DELIMITER ;


DROP PROCEDURE IF EXISTS sp_get_stock_by_product_and_deposit;
DELIMITER $$

CREATE PROCEDURE sp_get_stock_by_product_and_deposit(
  IN p_idBusiness INT,
  IN p_idProduct INT,
  IN p_idDeposit INT
)
BEGIN
  SELECT
    s.idStock,
    s.idBusiness,
    s.idProduct,
    s.idDeposit,
    s.quantity,
    s.updated_at
  FROM stock s
  WHERE s.idBusiness = p_idBusiness
    AND s.idProduct = p_idProduct
    AND s.idDeposit = p_idDeposit
  LIMIT 1;
END$$

DELIMITER ;


DROP PROCEDURE IF EXISTS sp_search_products_for_stock;
DELIMITER $$

CREATE PROCEDURE sp_search_products_for_stock(
  IN p_idBusiness INT,
  IN p_search VARCHAR(160) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  IN p_limit INT
)
BEGIN
  SELECT
    p.idProduct,
    p.idBusiness,
    p.idProductCategory,
    pc.name AS product_category_name,
    p.barcode,
    p.name,
    p.description,
    p.image_url,
    p.price_cost,
    p.price_sale,
    p.price_wholesale,
    p.unit_type,
    COALESCE(SUM(s.quantity), 0) AS stock,
    p.stock_min,
    p.is_active,
    p.created_at,
    p.updated_at
  FROM products p
  LEFT JOIN product_categories pc
    ON pc.idProductCategory = p.idProductCategory
    AND pc.idBusiness = p.idBusiness
  LEFT JOIN stock s
    ON s.idBusiness = p.idBusiness
    AND s.idProduct = p.idProduct
  WHERE p.idBusiness = p_idBusiness
    AND (
      p_search IS NULL
      OR p_search = ''
      OR p.name COLLATE utf8mb4_unicode_ci LIKE CONCAT('%', p_search COLLATE utf8mb4_unicode_ci, '%')
      OR p.barcode COLLATE utf8mb4_unicode_ci LIKE CONCAT('%', p_search COLLATE utf8mb4_unicode_ci, '%')
      OR p.description COLLATE utf8mb4_unicode_ci LIKE CONCAT('%', p_search COLLATE utf8mb4_unicode_ci, '%')
    )
  GROUP BY
    p.idProduct,
    p.idBusiness,
    p.idProductCategory,
    pc.name,
    p.barcode,
    p.name,
    p.description,
    p.image_url,
    p.price_cost,
    p.price_sale,
    p.price_wholesale,
    p.unit_type,
    p.stock_min,
    p.is_active,
    p.created_at,
    p.updated_at
  ORDER BY
    CASE WHEN p.is_active = 1 THEN 0 ELSE 1 END ASC,
    p.name ASC,
    p.idProduct ASC
  LIMIT p_limit;
END$$

DELIMITER ;


DROP PROCEDURE IF EXISTS sp_get_critical_stock_report;
DELIMITER $$

CREATE PROCEDURE sp_get_critical_stock_report(
  IN p_idBusiness INT,
  IN p_idDeposit INT,
  IN p_searchProduct VARCHAR(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  IN p_alertStatus VARCHAR(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  IN p_maxQuantity DECIMAL(18,2)
)
BEGIN
  SELECT *
  FROM (
    SELECT
      s.idStock,
      s.idBusiness,
      s.idProduct,
      p.name AS product_name,
      p.barcode,
      p.image_url AS image_url,
      p.unit_type,
      p.price_cost,
      s.idDeposit,
      d.name AS deposit_name,
      s.quantity,
      p.stock_min,
      CASE
        WHEN s.quantity = 0 THEN 'CRITICAL_ZERO'
        WHEN s.quantity > 0 AND s.quantity < p.stock_min THEN 'CRITICAL_LOW'
        WHEN s.quantity = p.stock_min THEN 'CRITICAL_EQUAL'
      END AS alert_status,
      CASE
        WHEN s.quantity = 0 THEN 'Sin stock'
        WHEN s.quantity > 0 AND s.quantity < p.stock_min THEN 'Bajo minimo'
        WHEN s.quantity = p.stock_min THEN 'En el minimo'
      END AS alert_message
    FROM stock s
    INNER JOIN products p
      ON p.idProduct = s.idProduct
      AND p.idBusiness = s.idBusiness
    INNER JOIN deposits d
      ON d.idDeposit = s.idDeposit
      AND d.idBusiness = s.idBusiness
    WHERE s.idBusiness = p_idBusiness
      AND p.is_active = 1
      AND d.is_active = 1
      AND s.quantity <= p.stock_min
      AND (p_maxQuantity IS NULL OR s.quantity <= p_maxQuantity)
      AND (p_idDeposit IS NULL OR s.idDeposit = p_idDeposit)
      AND (
        p_searchProduct IS NULL
        OR p_searchProduct = ''
        OR p.name COLLATE utf8mb4_unicode_ci LIKE CONCAT('%', p_searchProduct COLLATE utf8mb4_unicode_ci, '%')
        OR p.barcode COLLATE utf8mb4_unicode_ci LIKE CONCAT('%', p_searchProduct COLLATE utf8mb4_unicode_ci, '%')
      )
  ) critical_stock
  WHERE critical_stock.alert_status IS NOT NULL
    AND (
      p_alertStatus IS NULL
      OR p_alertStatus = ''
      OR critical_stock.alert_status COLLATE utf8mb4_unicode_ci = p_alertStatus COLLATE utf8mb4_unicode_ci
    )
  ORDER BY
    CASE
      WHEN critical_stock.alert_status = 'CRITICAL_ZERO' THEN 1
      WHEN critical_stock.alert_status = 'CRITICAL_LOW' THEN 2
      WHEN critical_stock.alert_status = 'CRITICAL_EQUAL' THEN 3
      ELSE 4
    END ASC,
    critical_stock.quantity ASC,
    critical_stock.product_name ASC;
END$$

DELIMITER ;

/* ============================================================
   END: procedures/stock.sql
   ============================================================ */

/* ============================================================
   BEGIN: procedures/stock_movements.sql
   ============================================================ */

DROP PROCEDURE IF EXISTS sp_process_stock_adjustment;
DELIMITER $$

CREATE PROCEDURE sp_process_stock_adjustment(
  IN p_idBusiness INT,
  IN p_idUser INT,
  IN p_idProduct INT,
  IN p_idDeposit INT,
  IN p_quantity DECIMAL(18,2),
  IN p_movement_type VARCHAR(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  IN p_observation VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci
)
BEGIN
  DECLARE v_current_quantity DECIMAL(18,2);
  DECLARE v_idMovement INT;
  DECLARE v_unit_type VARCHAR(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    RESIGNAL;
  END;

  IF p_movement_type NOT IN ('ADJUSTMENT_IN', 'ADJUSTMENT_OUT') THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'Tipo de ajuste invalido';
  END IF;

  IF p_quantity IS NULL OR p_quantity <= 0 THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'La cantidad debe ser mayor a cero';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM stock
    WHERE idBusiness = p_idBusiness
      AND idProduct = p_idProduct
      AND idDeposit = p_idDeposit
  ) THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'El producto no tiene stock registrado en el deposito indicado';
  END IF;

  SELECT s.quantity, p.unit_type
  INTO v_current_quantity, v_unit_type
  FROM stock s
  INNER JOIN products p
    ON p.idProduct = s.idProduct
    AND p.idBusiness = s.idBusiness
  WHERE s.idBusiness = p_idBusiness
    AND s.idProduct = p_idProduct
    AND s.idDeposit = p_idDeposit
  LIMIT 1;

  IF v_unit_type = 'UNIT' AND p_quantity <> FLOOR(p_quantity) THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'Los productos por unidad solo permiten cantidades enteras';
  END IF;

  IF p_movement_type = 'ADJUSTMENT_OUT' AND v_current_quantity < p_quantity THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'Stock insuficiente para realizar el ajuste';
  END IF;

  START TRANSACTION;

  UPDATE stock
  SET
    quantity = CASE
      WHEN p_movement_type = 'ADJUSTMENT_IN' THEN quantity + p_quantity
      ELSE quantity - p_quantity
    END,
    updated_at = NOW()
  WHERE idBusiness = p_idBusiness
    AND idProduct = p_idProduct
    AND idDeposit = p_idDeposit;

  INSERT INTO stock_movements (
    idBusiness,
    idProduct,
    idUser,
    movement_type,
    idDepositFrom,
    idDepositTo,
    quantity,
    reference_type,
    reference_id,
    observation,
    created_at
  )
  VALUES (
    p_idBusiness,
    p_idProduct,
    p_idUser,
    p_movement_type,
    CASE WHEN p_movement_type = 'ADJUSTMENT_OUT' THEN p_idDeposit ELSE NULL END,
    CASE WHEN p_movement_type = 'ADJUSTMENT_IN' THEN p_idDeposit ELSE NULL END,
    p_quantity,
    'ADJUSTMENT',
    NULL,
    p_observation,
    NOW()
  );

  SET v_idMovement = LAST_INSERT_ID();

  UPDATE stock_movements
  SET reference_id = v_idMovement
  WHERE idStockMovement = v_idMovement;

  COMMIT;

  CALL sp_get_stock_movements(p_idBusiness, 15, 0, NULL, NULL, NULL);
END$$

DELIMITER ;


DROP PROCEDURE IF EXISTS sp_process_stock_transfer;
DELIMITER $$

CREATE PROCEDURE sp_process_stock_transfer(
  IN p_idBusiness INT,
  IN p_idUser INT,
  IN p_idProduct INT,
  IN p_idDepositFrom INT,
  IN p_idDepositTo INT,
  IN p_quantity DECIMAL(18,2),
  IN p_observation VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci
)
BEGIN
  DECLARE v_current_quantity DECIMAL(18,2);
  DECLARE v_reference_id INT;
  DECLARE v_unit_type VARCHAR(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    RESIGNAL;
  END;

  IF p_idDepositFrom = p_idDepositTo THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'El deposito origen y destino deben ser diferentes';
  END IF;

  IF p_quantity IS NULL OR p_quantity <= 0 THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'La cantidad debe ser mayor a cero';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM deposits
    WHERE idBusiness = p_idBusiness
      AND idDeposit = p_idDepositFrom
      AND is_active = 1
  ) OR NOT EXISTS (
    SELECT 1
    FROM deposits
    WHERE idBusiness = p_idBusiness
      AND idDeposit = p_idDepositTo
      AND is_active = 1
  ) THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'Los depositos indicados deben pertenecer al negocio y estar activos';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM stock
    WHERE idBusiness = p_idBusiness
      AND idProduct = p_idProduct
      AND idDeposit = p_idDepositFrom
  ) THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'El producto no tiene stock registrado en el deposito origen';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM stock
    WHERE idBusiness = p_idBusiness
      AND idProduct = p_idProduct
      AND idDeposit = p_idDepositTo
  ) THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'Primero debe dar de alta el stock del producto en el deposito al que desea transferir';
  END IF;

  SELECT s.quantity, p.unit_type
  INTO v_current_quantity, v_unit_type
  FROM stock s
  INNER JOIN products p
    ON p.idProduct = s.idProduct
    AND p.idBusiness = s.idBusiness
  WHERE s.idBusiness = p_idBusiness
    AND s.idProduct = p_idProduct
    AND s.idDeposit = p_idDepositFrom
  LIMIT 1;

  IF v_unit_type = 'UNIT' AND p_quantity <> FLOOR(p_quantity) THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'Los productos por unidad solo permiten cantidades enteras';
  END IF;

  IF v_current_quantity < p_quantity THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'Stock insuficiente para realizar la transferencia';
  END IF;

  START TRANSACTION;

  UPDATE stock
  SET
    quantity = quantity - p_quantity,
    updated_at = NOW()
  WHERE idBusiness = p_idBusiness
    AND idProduct = p_idProduct
    AND idDeposit = p_idDepositFrom;

  UPDATE stock
  SET
    quantity = quantity + p_quantity,
    updated_at = NOW()
  WHERE idBusiness = p_idBusiness
    AND idProduct = p_idProduct
    AND idDeposit = p_idDepositTo;

  INSERT INTO stock_movements (
    idBusiness,
    idProduct,
    idUser,
    movement_type,
    idDepositFrom,
    idDepositTo,
    quantity,
    reference_type,
    reference_id,
    observation,
    created_at
  )
  VALUES (
    p_idBusiness,
    p_idProduct,
    p_idUser,
    'TRANSFER_OUT',
    p_idDepositFrom,
    p_idDepositTo,
    p_quantity,
    'TRANSFER',
    NULL,
    p_observation,
    NOW()
  );

  SET v_reference_id = LAST_INSERT_ID();

  INSERT INTO stock_movements (
    idBusiness,
    idProduct,
    idUser,
    movement_type,
    idDepositFrom,
    idDepositTo,
    quantity,
    reference_type,
    reference_id,
    observation,
    created_at
  )
  VALUES (
    p_idBusiness,
    p_idProduct,
    p_idUser,
    'TRANSFER_IN',
    p_idDepositFrom,
    p_idDepositTo,
    p_quantity,
    'TRANSFER',
    v_reference_id,
    p_observation,
    NOW()
  );

  UPDATE stock_movements
  SET reference_id = v_reference_id
  WHERE idStockMovement = v_reference_id;

  COMMIT;

  CALL sp_get_stock_movements(p_idBusiness, 15, 0, NULL, NULL, NULL);
END$$

DELIMITER ;


DROP PROCEDURE IF EXISTS sp_get_stock_movements;
DELIMITER $$

CREATE PROCEDURE sp_get_stock_movements(
  IN p_idBusiness INT,
  IN p_limit INT,
  IN p_offset INT,
  IN p_movementType VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  IN p_idDeposit INT,
  IN p_search VARCHAR(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci
)
BEGIN
  SELECT
    sm.idStockMovement,
    sm.idBusiness,
    b.name AS business_name,
    sm.idProduct,
    p.name AS product_name,
    p.image_url AS product_image_url,
    sm.idUser,
    u.name AS user_name,
    sm.movement_type,
    sm.idDepositFrom,
    df.name AS deposit_from_name,
    sm.idDepositTo,
    dt.name AS deposit_to_name,
    sm.quantity,
    sm.reference_type,
    sm.reference_id,
    sm.observation,
    sm.created_at
  FROM stock_movements sm
  INNER JOIN businesses b ON b.idBusiness = sm.idBusiness
  INNER JOIN products p
    ON p.idProduct = sm.idProduct
    AND p.idBusiness = sm.idBusiness
  INNER JOIN users u ON u.idUser = sm.idUser
  LEFT JOIN deposits df
    ON df.idDeposit = sm.idDepositFrom
    AND df.idBusiness = sm.idBusiness
  LEFT JOIN deposits dt
    ON dt.idDeposit = sm.idDepositTo
    AND dt.idBusiness = sm.idBusiness
  WHERE sm.idBusiness = p_idBusiness
    AND (
      p_movementType IS NULL
      OR p_movementType = ''
      OR p_movementType = 'ALL'
      OR (p_movementType = 'IN' AND sm.movement_type IN (
        'PURCHASE', 'TRANSFER_IN', 'ADJUSTMENT_IN'
      ))
      OR (p_movementType = 'OUT' AND sm.movement_type IN (
        'SALE', 'TRANSFER_OUT', 'ADJUSTMENT_OUT'
      ))
      OR (p_movementType = 'TRANSFER' AND sm.movement_type IN (
        'TRANSFER_IN', 'TRANSFER_OUT'
      ))
      OR sm.movement_type = p_movementType
    )
    AND (
      p_idDeposit IS NULL
      OR sm.idDepositFrom = p_idDeposit
      OR sm.idDepositTo = p_idDeposit
    )
    AND (
      p_search IS NULL
      OR p_search = ''
      OR p.name COLLATE utf8mb4_unicode_ci LIKE CONCAT('%', p_search COLLATE utf8mb4_unicode_ci, '%')
      OR u.name COLLATE utf8mb4_unicode_ci LIKE CONCAT('%', p_search COLLATE utf8mb4_unicode_ci, '%')
    )
  ORDER BY sm.created_at DESC, sm.idStockMovement DESC
  LIMIT p_limit OFFSET p_offset;

  SELECT COUNT(*) AS totalRecords
  FROM stock_movements sm
  INNER JOIN products p
    ON p.idProduct = sm.idProduct
    AND p.idBusiness = sm.idBusiness
  INNER JOIN users u ON u.idUser = sm.idUser
  WHERE sm.idBusiness = p_idBusiness
    AND (
      p_movementType IS NULL
      OR p_movementType = ''
      OR p_movementType = 'ALL'
      OR (p_movementType = 'IN' AND sm.movement_type IN (
        'PURCHASE', 'TRANSFER_IN', 'ADJUSTMENT_IN'
      ))
      OR (p_movementType = 'OUT' AND sm.movement_type IN (
        'SALE', 'TRANSFER_OUT', 'ADJUSTMENT_OUT'
      ))
      OR (p_movementType = 'TRANSFER' AND sm.movement_type IN (
        'TRANSFER_IN', 'TRANSFER_OUT'
      ))
      OR sm.movement_type = p_movementType
    )
    AND (
      p_idDeposit IS NULL
      OR sm.idDepositFrom = p_idDeposit
      OR sm.idDepositTo = p_idDeposit
    )
    AND (
      p_search IS NULL
      OR p_search = ''
      OR p.name COLLATE utf8mb4_unicode_ci LIKE CONCAT('%', p_search COLLATE utf8mb4_unicode_ci, '%')
      OR u.name COLLATE utf8mb4_unicode_ci LIKE CONCAT('%', p_search COLLATE utf8mb4_unicode_ci, '%')
    );
END$$

DELIMITER ;

/* ============================================================
   END: procedures/stock_movements.sql
   ============================================================ */

/* ============================================================
   BEGIN: procedures/sale_payments.sql
   ============================================================ */


DROP PROCEDURE IF EXISTS sp_sale_payment_create;
DELIMITER $$

CREATE PROCEDURE sp_sale_payment_create(
  IN p_idBusiness INT,
  IN p_idSale INT,
  IN p_idPaymentMethod INT,
  IN p_amount DECIMAL(18,2),
  IN p_status VARCHAR(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  IN p_createdByUserId INT,
  IN p_idCashSession BIGINT,
  IN p_reference VARCHAR(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  IN p_observation VARCHAR(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci
)
BEGIN
  DECLARE v_idSalePayment BIGINT;
  DECLARE v_saleTotal DECIMAL(18,2);
  DECLARE v_activePaymentsTotal DECIMAL(18,2);
  DECLARE v_methodActive TINYINT;
  DECLARE v_cashSessionStatus VARCHAR(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

  IF p_status NOT IN ('PENDING', 'CONFIRMED') THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'INVALID_INITIAL_PAYMENT_STATUS';
  END IF;

  IF p_amount IS NULL OR p_amount <= 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'PAYMENT_AMOUNT_MUST_BE_POSITIVE';
  END IF;

  SELECT total
  INTO v_saleTotal
  FROM sales
  WHERE idBusiness = p_idBusiness
    AND idSale = p_idSale
    AND status = 'COMPLETED'
  LIMIT 1
  FOR UPDATE;

  IF v_saleTotal IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'SALE_NOT_FOUND_OR_NOT_ACTIVE';
  END IF;

  SELECT is_active
  INTO v_methodActive
  FROM payment_methods
  WHERE idBusiness = p_idBusiness
    AND idPaymentMethod = p_idPaymentMethod
  LIMIT 1;

  IF v_methodActive IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'PAYMENT_METHOD_NOT_FOUND';
  END IF;

  IF v_methodActive = 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'PAYMENT_METHOD_INACTIVE';
  END IF;

  IF p_status = 'CONFIRMED' THEN
    IF p_idCashSession IS NULL THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'OPEN_CASH_SESSION_REQUIRED';
    END IF;

    SELECT status
    INTO v_cashSessionStatus
    FROM cash_sessions
    WHERE idBusiness = p_idBusiness
      AND idCashSession = p_idCashSession
    LIMIT 1;

    IF v_cashSessionStatus IS NULL THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'CASH_SESSION_NOT_FOUND';
    END IF;

    IF v_cashSessionStatus <> 'OPEN' THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'CASH_SESSION_CLOSED';
    END IF;
  END IF;

  SELECT COALESCE(SUM(amount), 0)
  INTO v_activePaymentsTotal
  FROM sale_payments
  WHERE idBusiness = p_idBusiness
    AND idSale = p_idSale
    AND status IN ('PENDING', 'COLLECTED', 'CONFIRMED');

  IF v_activePaymentsTotal + p_amount > v_saleTotal THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'SALE_PAYMENT_OVERPAYMENT_NOT_ALLOWED';
  END IF;

  INSERT INTO sale_payments (
    idBusiness,
    idSale,
    idPaymentMethod,
    amount,
    status,
    created_by_user_id,
    confirmed_by_user_id,
    confirmed_at,
    idCashSession,
    reference,
    observation,
    created_at
  )
  VALUES (
    p_idBusiness,
    p_idSale,
    p_idPaymentMethod,
    p_amount,
    p_status,
    p_createdByUserId,
    CASE WHEN p_status = 'CONFIRMED' THEN p_createdByUserId ELSE NULL END,
    CASE WHEN p_status = 'CONFIRMED' THEN NOW() ELSE NULL END,
    CASE WHEN p_status = 'CONFIRMED' THEN p_idCashSession ELSE NULL END,
    NULLIF(TRIM(COALESCE(p_reference, '')), ''),
    NULLIF(TRIM(COALESCE(p_observation, '')), ''),
    NOW()
  );

  SET v_idSalePayment = LAST_INSERT_ID();

  INSERT INTO sale_payment_events (
    idBusiness,
    idSalePayment,
    event_type,
    previous_status,
    new_status,
    metadata,
    created_by_user_id,
    created_at
  )
  VALUES (
    p_idBusiness,
    v_idSalePayment,
    'PAYMENT_CREATED',
    NULL,
    p_status,
    JSON_OBJECT('amount', p_amount, 'idPaymentMethod', p_idPaymentMethod),
    p_createdByUserId,
    NOW()
  );

  CALL sp_sale_payment_get_by_id(p_idBusiness, v_idSalePayment);
END$$

DELIMITER ;


DROP PROCEDURE IF EXISTS sp_sale_payment_events_list;
DELIMITER $$

CREATE PROCEDURE sp_sale_payment_events_list(
  IN p_idBusiness INT,
  IN p_idSalePayment BIGINT
)
BEGIN
  SELECT
    spe.idSalePaymentEvent,
    spe.idBusiness,
    spe.idSalePayment,
    spe.event_type,
    spe.previous_status,
    spe.new_status,
    spe.metadata,
    metadataMethod.name AS metadata_payment_method_name,
    previousMethod.name AS previous_payment_method_name,
    newMethod.name AS new_payment_method_name,
    metadataRegister.name AS metadata_cash_register_name,
    spe.created_by_user_id,
    u.name AS created_by_user_name,
    spe.created_at
  FROM sale_payment_events spe
  INNER JOIN sale_payments sp
    ON sp.idBusiness = spe.idBusiness
    AND sp.idSalePayment = spe.idSalePayment
  LEFT JOIN payment_methods metadataMethod
    ON metadataMethod.idBusiness = spe.idBusiness
    AND metadataMethod.idPaymentMethod = CAST(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(spe.metadata, '$.idPaymentMethod')), 'null') AS UNSIGNED)
  LEFT JOIN payment_methods previousMethod
    ON previousMethod.idBusiness = spe.idBusiness
    AND previousMethod.idPaymentMethod = CAST(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(spe.metadata, '$.previousIdPaymentMethod')), 'null') AS UNSIGNED)
  LEFT JOIN payment_methods newMethod
    ON newMethod.idBusiness = spe.idBusiness
    AND newMethod.idPaymentMethod = CAST(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(spe.metadata, '$.newIdPaymentMethod')), 'null') AS UNSIGNED)
  LEFT JOIN cash_sessions metadataSession
    ON metadataSession.idBusiness = spe.idBusiness
    AND metadataSession.idCashSession = CAST(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(spe.metadata, '$.idCashSession')), 'null') AS UNSIGNED)
  LEFT JOIN cash_registers metadataRegister
    ON metadataRegister.idBusiness = metadataSession.idBusiness
    AND metadataRegister.idCashRegister = metadataSession.idCashRegister
  LEFT JOIN users u ON u.idUser = spe.created_by_user_id
  WHERE spe.idBusiness = p_idBusiness
    AND spe.idSalePayment = p_idSalePayment
  ORDER BY spe.created_at ASC, spe.idSalePaymentEvent ASC;
END$$

DELIMITER ;


DROP PROCEDURE IF EXISTS sp_sale_payment_get_by_id;
DELIMITER $$

CREATE PROCEDURE sp_sale_payment_get_by_id(
  IN p_idBusiness INT,
  IN p_idSalePayment BIGINT
)
BEGIN
  SELECT
    sp.idSalePayment,
    sp.idBusiness,
    sp.idSale,
    s.sale_number,
    sp.idPaymentMethod,
    pm.code AS payment_method_code,
    pm.name AS payment_method_name,
    pm.affects_cash,
    sp.amount,
    sp.status,
    sp.created_by_user_id,
    createdUser.name AS created_by_user_name,
    sp.collected_by_user_id,
    collectedUser.name AS collected_by_user_name,
    sp.collected_at,
    sp.confirmed_by_user_id,
    confirmedUser.name AS confirmed_by_user_name,
    sp.confirmed_at,
    sp.cancelled_by_user_id,
    cancelledUser.name AS cancelled_by_user_name,
    sp.cancelled_at,
    sp.cancellation_reason,
    sp.idCashSession,
    sp.idCashSettlement,
    sp.reference,
    sp.observation,
    sp.created_at,
    sp.updated_at
  FROM sale_payments sp
  INNER JOIN sales s
    ON s.idBusiness = sp.idBusiness
    AND s.idSale = sp.idSale
  INNER JOIN payment_methods pm
    ON pm.idBusiness = sp.idBusiness
    AND pm.idPaymentMethod = sp.idPaymentMethod
  INNER JOIN users createdUser ON createdUser.idUser = sp.created_by_user_id
  LEFT JOIN users collectedUser ON collectedUser.idUser = sp.collected_by_user_id
  LEFT JOIN users confirmedUser ON confirmedUser.idUser = sp.confirmed_by_user_id
  LEFT JOIN users cancelledUser ON cancelledUser.idUser = sp.cancelled_by_user_id
  WHERE sp.idBusiness = p_idBusiness
    AND sp.idSalePayment = p_idSalePayment
  LIMIT 1;
END$$

DELIMITER ;


DROP PROCEDURE IF EXISTS sp_sale_payment_list_by_sale;
DELIMITER $$

CREATE PROCEDURE sp_sale_payment_list_by_sale(
  IN p_idBusiness INT,
  IN p_idSale INT
)
BEGIN
  SELECT
    sp.idSalePayment,
    sp.idBusiness,
    sp.idSale,
    s.sale_number,
    sp.idPaymentMethod,
    pm.code AS payment_method_code,
    pm.name AS payment_method_name,
    pm.affects_cash,
    sp.amount,
    sp.status,
    sp.created_by_user_id,
    createdUser.name AS created_by_user_name,
    sp.collected_by_user_id,
    collectedUser.name AS collected_by_user_name,
    sp.collected_at,
    sp.confirmed_by_user_id,
    confirmedUser.name AS confirmed_by_user_name,
    sp.confirmed_at,
    sp.cancelled_by_user_id,
    cancelledUser.name AS cancelled_by_user_name,
    sp.cancelled_at,
    sp.cancellation_reason,
    sp.idCashSession,
    sp.idCashSettlement,
    sp.reference,
    sp.observation,
    sp.created_at,
    sp.updated_at
  FROM sale_payments sp
  INNER JOIN sales s
    ON s.idBusiness = sp.idBusiness
    AND s.idSale = sp.idSale
  INNER JOIN payment_methods pm
    ON pm.idBusiness = sp.idBusiness
    AND pm.idPaymentMethod = sp.idPaymentMethod
  INNER JOIN users createdUser ON createdUser.idUser = sp.created_by_user_id
  LEFT JOIN users collectedUser ON collectedUser.idUser = sp.collected_by_user_id
  LEFT JOIN users confirmedUser ON confirmedUser.idUser = sp.confirmed_by_user_id
  LEFT JOIN users cancelledUser ON cancelledUser.idUser = sp.cancelled_by_user_id
  WHERE sp.idBusiness = p_idBusiness
    AND sp.idSale = p_idSale
  ORDER BY sp.created_at ASC, sp.idSalePayment ASC;
END$$

DELIMITER ;


DROP PROCEDURE IF EXISTS sp_sale_payment_update_pending;
DELIMITER $$

CREATE PROCEDURE sp_sale_payment_update_pending(
  IN p_idBusiness INT,
  IN p_idSalePayment BIGINT,
  IN p_actorUserId INT,
  IN p_idPaymentMethod INT,
  IN p_amount DECIMAL(18,2),
  IN p_reference VARCHAR(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  IN p_observation VARCHAR(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci
)
BEGIN
  DECLARE v_idSale INT;
  DECLARE v_saleTotal DECIMAL(18,2);
  DECLARE v_otherPaymentsTotal DECIMAL(18,2);
  DECLARE v_previousStatus VARCHAR(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
  DECLARE v_previousMethod INT;
  DECLARE v_methodActive TINYINT;

  SELECT idSale, status, idPaymentMethod
  INTO v_idSale, v_previousStatus, v_previousMethod
  FROM sale_payments
  WHERE idBusiness = p_idBusiness
    AND idSalePayment = p_idSalePayment
  LIMIT 1
  FOR UPDATE;

  IF v_idSale IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'SALE_PAYMENT_NOT_FOUND';
  END IF;

  IF v_previousStatus <> 'PENDING' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'ONLY_PENDING_PAYMENT_CAN_BE_UPDATED';
  END IF;

  IF p_amount IS NULL OR p_amount <= 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'PAYMENT_AMOUNT_MUST_BE_POSITIVE';
  END IF;

  SELECT total
  INTO v_saleTotal
  FROM sales
  WHERE idBusiness = p_idBusiness
    AND idSale = v_idSale
    AND status = 'COMPLETED'
  LIMIT 1
  FOR UPDATE;

  SELECT is_active
  INTO v_methodActive
  FROM payment_methods
  WHERE idBusiness = p_idBusiness
    AND idPaymentMethod = p_idPaymentMethod
  LIMIT 1;

  IF v_methodActive IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'PAYMENT_METHOD_NOT_FOUND';
  END IF;

  IF v_methodActive = 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'PAYMENT_METHOD_INACTIVE';
  END IF;

  SELECT COALESCE(SUM(amount), 0)
  INTO v_otherPaymentsTotal
  FROM sale_payments
  WHERE idBusiness = p_idBusiness
    AND idSale = v_idSale
    AND idSalePayment <> p_idSalePayment
    AND status IN ('PENDING', 'COLLECTED', 'CONFIRMED');

  IF v_otherPaymentsTotal + p_amount > v_saleTotal THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'SALE_PAYMENT_OVERPAYMENT_NOT_ALLOWED';
  END IF;

  UPDATE sale_payments
  SET
    idPaymentMethod = p_idPaymentMethod,
    amount = p_amount,
    reference = NULLIF(TRIM(COALESCE(p_reference, '')), ''),
    observation = NULLIF(TRIM(COALESCE(p_observation, '')), '')
  WHERE idBusiness = p_idBusiness
    AND idSalePayment = p_idSalePayment;

  INSERT INTO sale_payment_events (
    idBusiness,
    idSalePayment,
    event_type,
    previous_status,
    new_status,
    metadata,
    created_by_user_id
  )
  VALUES (
    p_idBusiness,
    p_idSalePayment,
    CASE WHEN v_previousMethod <> p_idPaymentMethod THEN 'PAYMENT_METHOD_CHANGED' ELSE 'PAYMENT_UPDATED' END,
    v_previousStatus,
    v_previousStatus,
    JSON_OBJECT('amount', p_amount, 'idPaymentMethod', p_idPaymentMethod),
    p_actorUserId
  );

  CALL sp_sale_payment_get_by_id(p_idBusiness, p_idSalePayment);
END$$

DELIMITER ;


DROP PROCEDURE IF EXISTS sp_sale_payment_cancel_pending;
DELIMITER $$

CREATE PROCEDURE sp_sale_payment_cancel_pending(
  IN p_idBusiness INT,
  IN p_idSalePayment BIGINT,
  IN p_actorUserId INT,
  IN p_reason VARCHAR(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci
)
BEGIN
  DECLARE v_status VARCHAR(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

  SELECT status
  INTO v_status
  FROM sale_payments
  WHERE idBusiness = p_idBusiness
    AND idSalePayment = p_idSalePayment
  LIMIT 1
  FOR UPDATE;

  IF v_status IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'SALE_PAYMENT_NOT_FOUND';
  END IF;

  IF v_status <> 'PENDING' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'ONLY_PENDING_PAYMENT_CAN_BE_CANCELLED';
  END IF;

  UPDATE sale_payments
  SET
    status = 'CANCELLED',
    cancelled_by_user_id = p_actorUserId,
    cancelled_at = NOW(),
    cancellation_reason = NULLIF(TRIM(COALESCE(p_reason, '')), '')
  WHERE idBusiness = p_idBusiness
    AND idSalePayment = p_idSalePayment;

  INSERT INTO sale_payment_events (
    idBusiness,
    idSalePayment,
    event_type,
    previous_status,
    new_status,
    metadata,
    created_by_user_id
  )
  VALUES (
    p_idBusiness,
    p_idSalePayment,
    'PAYMENT_CANCELLED',
    v_status,
    'CANCELLED',
    JSON_OBJECT('reason', p_reason),
    p_actorUserId
  );

  CALL sp_sale_payment_get_by_id(p_idBusiness, p_idSalePayment);
END$$

DELIMITER ;


DROP PROCEDURE IF EXISTS sp_sale_payment_collect;
DELIMITER $$

CREATE PROCEDURE sp_sale_payment_collect(
  IN p_idBusiness INT,
  IN p_idSalePayment BIGINT,
  IN p_actorUserId INT,
  IN p_idPaymentMethod INT,
  IN p_observation VARCHAR(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci
)
BEGIN
  DECLARE v_status VARCHAR(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
  DECLARE v_currentMethod INT;
  DECLARE v_finalMethod INT;
  DECLARE v_methodAffectsCash TINYINT;
  DECLARE v_methodActive TINYINT;
  DECLARE v_deliveryAssignedUser INT;
  DECLARE v_deliveryStatus VARCHAR(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    RESIGNAL;
  END;

  START TRANSACTION;

  SELECT sp.status, sp.idPaymentMethod, sd.assigned_to_user_id, sd.status
  INTO v_status, v_currentMethod, v_deliveryAssignedUser, v_deliveryStatus
  FROM sale_payments sp
  INNER JOIN sale_deliveries sd
    ON sd.idBusiness = sp.idBusiness
    AND sd.idSale = sp.idSale
  WHERE sp.idBusiness = p_idBusiness
    AND sp.idSalePayment = p_idSalePayment
  LIMIT 1
  FOR UPDATE;

  IF v_status IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'SALE_PAYMENT_NOT_FOUND';
  END IF;

  IF v_status <> 'PENDING' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'ONLY_PENDING_PAYMENT_CAN_BE_COLLECTED';
  END IF;

  IF v_deliveryStatus NOT IN ('OUT_FOR_DELIVERY', 'DELIVERED') THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'DELIVERY_MUST_BE_OUT_FOR_DELIVERY';
  END IF;

  IF v_deliveryAssignedUser IS NULL OR v_deliveryAssignedUser <> p_actorUserId THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'DELIVERY_PAYMENT_FORBIDDEN';
  END IF;

  SET v_finalMethod = COALESCE(p_idPaymentMethod, v_currentMethod);

  SELECT is_active, affects_cash
  INTO v_methodActive, v_methodAffectsCash
  FROM payment_methods
  WHERE idBusiness = p_idBusiness
    AND idPaymentMethod = v_finalMethod
  LIMIT 1;

  IF v_methodActive IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'PAYMENT_METHOD_NOT_FOUND';
  END IF;

  IF v_methodActive = 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'PAYMENT_METHOD_INACTIVE';
  END IF;

  IF v_methodAffectsCash <> 1 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'DELIVERY_COLLECTION_REQUIRES_CASH_METHOD';
  END IF;

  IF p_idPaymentMethod IS NOT NULL AND p_idPaymentMethod <> v_currentMethod THEN
    UPDATE sale_payments
    SET idPaymentMethod = v_finalMethod
    WHERE idBusiness = p_idBusiness
      AND idSalePayment = p_idSalePayment;

    INSERT INTO sale_payment_events (
      idBusiness,
      idSalePayment,
      event_type,
      previous_status,
      new_status,
      metadata,
      created_by_user_id
    )
    VALUES (
      p_idBusiness,
      p_idSalePayment,
      'PAYMENT_METHOD_CHANGED',
      v_status,
      v_status,
      JSON_OBJECT('previousIdPaymentMethod', v_currentMethod, 'newIdPaymentMethod', v_finalMethod),
      p_actorUserId
    );
  END IF;

  UPDATE sale_payments
  SET
    status = 'COLLECTED',
    collected_by_user_id = p_actorUserId,
    collected_at = NOW(),
    observation = COALESCE(NULLIF(TRIM(COALESCE(p_observation, '')), ''), observation)
  WHERE idBusiness = p_idBusiness
    AND idSalePayment = p_idSalePayment;

  INSERT INTO sale_payment_events (
    idBusiness,
    idSalePayment,
    event_type,
    previous_status,
    new_status,
    metadata,
    created_by_user_id
  )
  VALUES (
    p_idBusiness,
    p_idSalePayment,
    'PAYMENT_COLLECTED',
    v_status,
    'COLLECTED',
    JSON_OBJECT('collectedByUserId', p_actorUserId),
    p_actorUserId
  );

  COMMIT;

  CALL sp_sale_payment_get_by_id(p_idBusiness, p_idSalePayment);
END$$

DELIMITER ;


DROP PROCEDURE IF EXISTS sp_sale_payment_confirm;
DELIMITER $$

CREATE PROCEDURE sp_sale_payment_confirm(
  IN p_idBusiness INT,
  IN p_idSalePayment BIGINT,
  IN p_actorUserId INT,
  IN p_idCashSession BIGINT
)
BEGIN
  DECLARE v_status VARCHAR(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
  DECLARE v_cashSessionStatus VARCHAR(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
  DECLARE v_methodAffectsCash TINYINT DEFAULT 0;
  DECLARE v_deliveryAssignedUser INT;
  DECLARE v_deliveryStatus VARCHAR(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    RESIGNAL;
  END;

  START TRANSACTION;

  SELECT sp.status, COALESCE(pm.affects_cash, 0), sd.assigned_to_user_id, sd.status
  INTO v_status, v_methodAffectsCash, v_deliveryAssignedUser, v_deliveryStatus
  FROM sale_payments sp
  INNER JOIN payment_methods pm
    ON pm.idBusiness = sp.idBusiness
    AND pm.idPaymentMethod = sp.idPaymentMethod
  LEFT JOIN sale_deliveries sd
    ON sd.idBusiness = sp.idBusiness
    AND sd.idSale = sp.idSale
  WHERE sp.idBusiness = p_idBusiness
    AND sp.idSalePayment = p_idSalePayment
  LIMIT 1
  FOR UPDATE;

  IF v_status IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'SALE_PAYMENT_NOT_FOUND';
  END IF;

  IF v_status = 'COLLECTED' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'COLLECTED_PAYMENT_REQUIRES_CASH_SETTLEMENT';
  END IF;

  IF v_status <> 'PENDING' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'ONLY_PENDING_PAYMENT_CAN_BE_CONFIRMED';
  END IF;

  IF v_methodAffectsCash = 1
    AND v_deliveryAssignedUser IS NOT NULL
    AND v_deliveryStatus IN ('ASSIGNED', 'OUT_FOR_DELIVERY', 'FAILED', 'DELIVERED')
  THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'DELIVERY_CASH_PAYMENT_REQUIRES_COLLECTION';
  END IF;

  SELECT status
  INTO v_cashSessionStatus
  FROM cash_sessions
  WHERE idBusiness = p_idBusiness
    AND idCashSession = p_idCashSession
  LIMIT 1;

  IF v_cashSessionStatus IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'CASH_SESSION_NOT_FOUND';
  END IF;

  IF v_cashSessionStatus <> 'OPEN' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'CASH_SESSION_CLOSED';
  END IF;

  UPDATE sale_payments
  SET
    status = 'CONFIRMED',
    confirmed_by_user_id = p_actorUserId,
    confirmed_at = NOW(),
    idCashSession = p_idCashSession
  WHERE idBusiness = p_idBusiness
    AND idSalePayment = p_idSalePayment;

  INSERT INTO sale_payment_events (
    idBusiness,
    idSalePayment,
    event_type,
    previous_status,
    new_status,
    metadata,
    created_by_user_id
  )
  VALUES (
    p_idBusiness,
    p_idSalePayment,
    'PAYMENT_CONFIRMED',
    v_status,
    'CONFIRMED',
    JSON_OBJECT('idCashSession', p_idCashSession),
    p_actorUserId
  );

  COMMIT;

  CALL sp_sale_payment_get_by_id(p_idBusiness, p_idSalePayment);
END$$

DELIMITER ;


DROP PROCEDURE IF EXISTS sp_sale_payment_summary_by_sale;
DELIMITER $$

CREATE PROCEDURE sp_sale_payment_summary_by_sale(
  IN p_idBusiness INT,
  IN p_idSale INT
)
BEGIN
  SELECT
    s.idSale,
    s.total,
    COALESCE(SUM(CASE WHEN sp.status = 'CONFIRMED' THEN sp.amount ELSE 0 END), 0) AS confirmedAmount,
    COALESCE(SUM(CASE WHEN sp.status = 'COLLECTED' THEN sp.amount ELSE 0 END), 0) AS collectedAmount,
    COALESCE(SUM(CASE WHEN sp.status = 'PENDING' THEN sp.amount ELSE 0 END), 0) AS pendingPlannedAmount,
    COALESCE(SUM(CASE WHEN sp.status IN ('COLLECTED','CONFIRMED') THEN sp.amount ELSE 0 END), 0) AS paidAmount,
    s.total - COALESCE(SUM(CASE WHEN sp.status IN ('COLLECTED','CONFIRMED') THEN sp.amount ELSE 0 END), 0) AS balanceDue,
    CASE
      WHEN COALESCE(SUM(CASE WHEN sp.status IN ('COLLECTED','CONFIRMED') THEN sp.amount ELSE 0 END), 0) = 0 THEN 'UNPAID'
      WHEN COALESCE(SUM(CASE WHEN sp.status IN ('COLLECTED','CONFIRMED') THEN sp.amount ELSE 0 END), 0) < s.total THEN 'PARTIALLY_PAID'
      ELSE 'PAID'
    END AS paymentStatus,
    GROUP_CONCAT(DISTINCT pm.name ORDER BY pm.name SEPARATOR ', ') AS paymentMethods
  FROM sales s
  LEFT JOIN sale_payments sp
    ON sp.idBusiness = s.idBusiness
    AND sp.idSale = s.idSale
    AND sp.status <> 'CANCELLED'
  LEFT JOIN payment_methods pm
    ON pm.idBusiness = sp.idBusiness
    AND pm.idPaymentMethod = sp.idPaymentMethod
  WHERE s.idBusiness = p_idBusiness
    AND s.idSale = p_idSale
  GROUP BY s.idSale, s.total;
END$$

DELIMITER ;

/* ============================================================
   END: procedures/sale_payments.sql
   ============================================================ */

/* ============================================================
   BEGIN: procedures/deliveries.sql
   ============================================================ */

DROP PROCEDURE IF EXISTS sp_delivery_create;
DELIMITER $$

CREATE PROCEDURE sp_delivery_create(
  IN p_idBusiness INT,
  IN p_idSale INT,
  IN p_createdByUserId INT,
  IN p_assignedToUserId INT,
  IN p_recipientName VARCHAR(160) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  IN p_recipientPhone VARCHAR(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  IN p_deliveryAddress VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  IN p_deliveryReference VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  IN p_scheduledAt DATETIME,
  IN p_observation VARCHAR(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci
)
BEGIN
  DECLARE v_idSaleDelivery BIGINT;
  DECLARE v_initialStatus VARCHAR(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'PENDING';

  IF p_assignedToUserId IS NOT NULL THEN
    SET v_initialStatus = 'ASSIGNED';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM sales
    WHERE idBusiness = p_idBusiness
      AND idSale = p_idSale
      AND status = 'COMPLETED'
  ) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'SALE_NOT_FOUND';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM sale_deliveries
    WHERE idBusiness = p_idBusiness
      AND idSale = p_idSale
  ) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'SALE_ALREADY_HAS_DELIVERY';
  END IF;

  IF p_assignedToUserId IS NOT NULL AND NOT EXISTS (
    SELECT 1
    FROM business_users bu
    INNER JOIN users u ON u.idUser = bu.idUser
    WHERE bu.idBusiness = p_idBusiness
      AND bu.idUser = p_assignedToUserId
      AND bu.role = 'DELIVERY'
      AND bu.is_active = 1
      AND u.is_active = 1
  ) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'DELIVERY_USER_NOT_FOUND';
  END IF;

  INSERT INTO sale_deliveries (
    idBusiness,
    idSale,
    assigned_to_user_id,
    created_by_user_id,
    status,
    recipient_name,
    recipient_phone,
    delivery_address,
    delivery_reference,
    scheduled_at,
    assigned_at,
    observation,
    created_at,
    updated_at
  )
  VALUES (
    p_idBusiness,
    p_idSale,
    p_assignedToUserId,
    p_createdByUserId,
    v_initialStatus,
    p_recipientName,
    p_recipientPhone,
    p_deliveryAddress,
    p_deliveryReference,
    p_scheduledAt,
    IF(p_assignedToUserId IS NULL, NULL, NOW()),
    p_observation,
    NOW(),
    NOW()
  );

  SET v_idSaleDelivery = LAST_INSERT_ID();

  INSERT INTO delivery_events (
    idBusiness,
    idSaleDelivery,
    event_type,
    previous_status,
    new_status,
    metadata,
    created_by_user_id
  )
  VALUES (
    p_idBusiness,
    v_idSaleDelivery,
    'DELIVERY_CREATED',
    NULL,
    v_initialStatus,
    JSON_OBJECT('assignedToUserId', p_assignedToUserId, 'scheduledAt', p_scheduledAt),
    p_createdByUserId
  );

  CALL sp_delivery_get_by_id(p_idBusiness, v_idSaleDelivery);
END$$

DELIMITER ;


DROP PROCEDURE IF EXISTS sp_delivery_events_list;
DELIMITER $$

CREATE PROCEDURE sp_delivery_events_list(
  IN p_idBusiness INT,
  IN p_idSaleDelivery BIGINT
)
BEGIN
  SELECT
    de.idDeliveryEvent,
    de.idBusiness,
    de.idSaleDelivery,
    de.event_type,
    de.previous_status,
    de.new_status,
    de.metadata,
    de.created_by_user_id,
    u.name AS created_by_user_name,
    de.created_at
  FROM delivery_events de
  INNER JOIN sale_deliveries sd
    ON sd.idBusiness = de.idBusiness
    AND sd.idSaleDelivery = de.idSaleDelivery
  LEFT JOIN users u ON u.idUser = de.created_by_user_id
  WHERE de.idBusiness = p_idBusiness
    AND de.idSaleDelivery = p_idSaleDelivery
  ORDER BY de.created_at ASC, de.idDeliveryEvent ASC;
END$$

DELIMITER ;


DROP PROCEDURE IF EXISTS sp_delivery_get_by_id;
DELIMITER $$

CREATE PROCEDURE sp_delivery_get_by_id(
  IN p_idBusiness INT,
  IN p_idSaleDelivery BIGINT
)
BEGIN
  SELECT
    sd.idSaleDelivery,
    sd.idBusiness,
    sd.idSale,
    s.sale_number,
    s.total,
    sd.assigned_to_user_id,
    assigned_user.name AS assigned_user_name,
    sd.created_by_user_id,
    creator.name AS created_by_user_name,
    sd.status,
    sd.recipient_name,
    sd.recipient_phone,
    sd.delivery_address,
    sd.delivery_reference,
    sd.scheduled_at,
    sd.assigned_at,
    sd.out_for_delivery_at,
    sd.delivered_at,
    sd.failed_at,
    sd.cancelled_at,
    sd.failure_reason,
    sd.observation,
    sd.created_at,
    sd.updated_at
  FROM sale_deliveries sd
  INNER JOIN sales s
    ON s.idSale = sd.idSale
    AND s.idBusiness = sd.idBusiness
  LEFT JOIN users assigned_user ON assigned_user.idUser = sd.assigned_to_user_id
  LEFT JOIN users creator ON creator.idUser = sd.created_by_user_id
  WHERE sd.idBusiness = p_idBusiness
    AND sd.idSaleDelivery = p_idSaleDelivery
  LIMIT 1;
END$$

DELIMITER ;


DROP PROCEDURE IF EXISTS sp_deliveries_list;
DELIMITER $$

CREATE PROCEDURE sp_deliveries_list(
  IN p_idBusiness INT,
  IN p_limit INT,
  IN p_offset INT,
  IN p_status VARCHAR(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  IN p_assignedToUserId INT,
  IN p_search VARCHAR(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci
)
BEGIN
  SELECT
    sd.idSaleDelivery,
    sd.idBusiness,
    sd.idSale,
    s.sale_number,
    s.total,
    sd.assigned_to_user_id,
    assigned_user.name AS assigned_user_name,
    sd.created_by_user_id,
    creator.name AS created_by_user_name,
    sd.status,
    sd.recipient_name,
    sd.recipient_phone,
    sd.delivery_address,
    sd.delivery_reference,
    sd.scheduled_at,
    sd.assigned_at,
    sd.out_for_delivery_at,
    sd.delivered_at,
    sd.failed_at,
    sd.cancelled_at,
    sd.failure_reason,
    sd.observation,
    sd.created_at,
    sd.updated_at
  FROM sale_deliveries sd
  INNER JOIN sales s
    ON s.idSale = sd.idSale
    AND s.idBusiness = sd.idBusiness
  LEFT JOIN users assigned_user ON assigned_user.idUser = sd.assigned_to_user_id
  LEFT JOIN users creator ON creator.idUser = sd.created_by_user_id
  WHERE sd.idBusiness = p_idBusiness
    AND (p_status IS NULL OR sd.status = p_status)
    AND (p_assignedToUserId IS NULL OR sd.assigned_to_user_id = p_assignedToUserId)
    AND (
      p_search IS NULL
      OR p_search = ''
      OR s.sale_number COLLATE utf8mb4_unicode_ci LIKE CONCAT('%', p_search COLLATE utf8mb4_unicode_ci, '%')
      OR sd.recipient_name COLLATE utf8mb4_unicode_ci LIKE CONCAT('%', p_search COLLATE utf8mb4_unicode_ci, '%')
      OR sd.delivery_address COLLATE utf8mb4_unicode_ci LIKE CONCAT('%', p_search COLLATE utf8mb4_unicode_ci, '%')
    )
  ORDER BY sd.created_at DESC, sd.idSaleDelivery DESC
  LIMIT p_limit OFFSET p_offset;

  SELECT COUNT(*) AS totalRecords
  FROM sale_deliveries sd
  INNER JOIN sales s
    ON s.idSale = sd.idSale
    AND s.idBusiness = sd.idBusiness
  WHERE sd.idBusiness = p_idBusiness
    AND (p_status IS NULL OR sd.status = p_status)
    AND (p_assignedToUserId IS NULL OR sd.assigned_to_user_id = p_assignedToUserId)
    AND (
      p_search IS NULL
      OR p_search = ''
      OR s.sale_number COLLATE utf8mb4_unicode_ci LIKE CONCAT('%', p_search COLLATE utf8mb4_unicode_ci, '%')
      OR sd.recipient_name COLLATE utf8mb4_unicode_ci LIKE CONCAT('%', p_search COLLATE utf8mb4_unicode_ci, '%')
      OR sd.delivery_address COLLATE utf8mb4_unicode_ci LIKE CONCAT('%', p_search COLLATE utf8mb4_unicode_ci, '%')
    );
END$$

DELIMITER ;


DROP PROCEDURE IF EXISTS sp_delivery_assign;
DELIMITER $$

CREATE PROCEDURE sp_delivery_assign(
  IN p_idBusiness INT,
  IN p_idSaleDelivery BIGINT,
  IN p_assignedToUserId INT,
  IN p_actorUserId INT
)
BEGIN
  DECLARE v_previousStatus VARCHAR(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
  DECLARE v_assignedToUserId INT;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    RESIGNAL;
  END;

  START TRANSACTION;

  SELECT status, assigned_to_user_id
  INTO v_previousStatus, v_assignedToUserId
  FROM sale_deliveries
  WHERE idBusiness = p_idBusiness
    AND idSaleDelivery = p_idSaleDelivery
  LIMIT 1
  FOR UPDATE;

  IF v_previousStatus IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'DELIVERY_NOT_FOUND';
  END IF;

  IF v_previousStatus NOT IN ('PENDING', 'ASSIGNED') THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'DELIVERY_CANNOT_BE_ASSIGNED';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM business_users bu
    INNER JOIN users u ON u.idUser = bu.idUser
    WHERE bu.idBusiness = p_idBusiness
      AND bu.idUser = p_assignedToUserId
      AND bu.role = 'DELIVERY'
      AND bu.is_active = 1
      AND u.is_active = 1
  ) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'DELIVERY_USER_NOT_FOUND';
  END IF;

  UPDATE sale_deliveries
  SET
    assigned_to_user_id = p_assignedToUserId,
    status = 'ASSIGNED',
    assigned_at = NOW(),
    updated_at = NOW()
  WHERE idBusiness = p_idBusiness
    AND idSaleDelivery = p_idSaleDelivery;

  INSERT INTO delivery_events
    (idBusiness, idSaleDelivery, event_type, previous_status, new_status, metadata, created_by_user_id)
  VALUES
    (p_idBusiness, p_idSaleDelivery, 'DELIVERY_ASSIGNED', v_previousStatus, 'ASSIGNED', JSON_OBJECT('assignedToUserId', p_assignedToUserId), p_actorUserId);

  COMMIT;

  CALL sp_delivery_get_by_id(p_idBusiness, p_idSaleDelivery);
END$$

DELIMITER ;


DROP PROCEDURE IF EXISTS sp_delivery_change_status;
DELIMITER $$

CREATE PROCEDURE sp_delivery_change_status(
  IN p_idBusiness INT,
  IN p_idSaleDelivery BIGINT,
  IN p_newStatus VARCHAR(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  IN p_actorUserId INT,
  IN p_actorCanViewAll TINYINT,
  IN p_failureReason VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  IN p_scheduledAt DATETIME,
  IN p_observation VARCHAR(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci
)
BEGIN
  DECLARE v_previousStatus VARCHAR(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
  DECLARE v_eventType VARCHAR(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
  DECLARE v_assignedToUserId INT;
  DECLARE v_actorExists INT DEFAULT 0;

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    RESIGNAL;
  END;

  START TRANSACTION;

  SELECT status, assigned_to_user_id
  INTO v_previousStatus, v_assignedToUserId
  FROM sale_deliveries
  WHERE idBusiness = p_idBusiness
    AND idSaleDelivery = p_idSaleDelivery
  LIMIT 1
  FOR UPDATE;

  IF v_previousStatus IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'DELIVERY_NOT_FOUND';
  END IF;

  SELECT COUNT(*)
  INTO v_actorExists
  FROM business_users
  WHERE idBusiness = p_idBusiness
    AND idUser = p_actorUserId
    AND is_active = 1;

  IF v_actorExists = 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'DELIVERY_ACTOR_NOT_FOUND';
  END IF;

  IF COALESCE(p_actorCanViewAll, 0) = 0
    AND (v_assignedToUserId IS NULL OR v_assignedToUserId <> p_actorUserId)
  THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'DELIVERY_FORBIDDEN';
  END IF;

  IF v_previousStatus IN ('DELIVERED', 'CANCELLED') THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'DELIVERY_FINAL_STATUS';
  END IF;

  IF p_newStatus = 'OUT_FOR_DELIVERY' AND v_previousStatus NOT IN ('ASSIGNED') THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'DELIVERY_MUST_BE_ASSIGNED';
  END IF;

  IF p_newStatus = 'DELIVERED' AND v_previousStatus NOT IN ('OUT_FOR_DELIVERY') THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'DELIVERY_MUST_BE_OUT_FOR_DELIVERY';
  END IF;

  IF p_newStatus = 'DELIVERED' AND EXISTS (
    SELECT 1
    FROM sale_deliveries sd
    INNER JOIN sale_payments sp
      ON sp.idBusiness = sd.idBusiness
      AND sp.idSale = sd.idSale
    INNER JOIN payment_methods pm
      ON pm.idBusiness = sp.idBusiness
      AND pm.idPaymentMethod = sp.idPaymentMethod
    WHERE sd.idBusiness = p_idBusiness
      AND sd.idSaleDelivery = p_idSaleDelivery
      AND sp.status = 'PENDING'
      AND pm.affects_cash = 1
    LIMIT 1
  ) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'DELIVERY_PENDING_CASH_PAYMENT_MUST_BE_COLLECTED';
  END IF;

  IF p_newStatus = 'FAILED' AND v_previousStatus <> 'OUT_FOR_DELIVERY' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'DELIVERY_CANNOT_FAIL';
  END IF;

  IF p_newStatus = 'PENDING' AND v_previousStatus <> 'FAILED' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'ONLY_FAILED_DELIVERY_CAN_BE_RESCHEDULED';
  END IF;

  IF p_newStatus = 'CANCELLED' AND v_previousStatus NOT IN ('PENDING', 'ASSIGNED', 'FAILED') THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'DELIVERY_CANNOT_BE_CANCELLED';
  END IF;

  SET v_eventType = CASE p_newStatus
    WHEN 'OUT_FOR_DELIVERY' THEN 'DELIVERY_OUT_FOR_DELIVERY'
    WHEN 'DELIVERED' THEN 'DELIVERY_DELIVERED'
    WHEN 'FAILED' THEN 'DELIVERY_FAILED'
    WHEN 'CANCELLED' THEN 'DELIVERY_CANCELLED'
    WHEN 'PENDING' THEN 'DELIVERY_RESCHEDULED'
    ELSE 'DELIVERY_RESCHEDULED'
  END;

  UPDATE sale_deliveries
  SET
    status = p_newStatus,
    assigned_to_user_id = IF(p_newStatus = 'PENDING', NULL, assigned_to_user_id),
    assigned_at = IF(p_newStatus = 'PENDING', NULL, assigned_at),
    scheduled_at = COALESCE(p_scheduledAt, scheduled_at),
    out_for_delivery_at = IF(p_newStatus = 'OUT_FOR_DELIVERY', NOW(), out_for_delivery_at),
    delivered_at = IF(p_newStatus = 'DELIVERED', NOW(), delivered_at),
    failed_at = IF(p_newStatus = 'FAILED', NOW(), failed_at),
    cancelled_at = IF(p_newStatus = 'CANCELLED', NOW(), cancelled_at),
    failure_reason = CASE
      WHEN p_newStatus = 'FAILED' THEN p_failureReason
      WHEN p_newStatus = 'PENDING' THEN NULL
      ELSE failure_reason
    END,
    observation = COALESCE(p_observation, observation),
    updated_at = NOW()
  WHERE idBusiness = p_idBusiness
    AND idSaleDelivery = p_idSaleDelivery;

  INSERT INTO delivery_events
    (idBusiness, idSaleDelivery, event_type, previous_status, new_status, metadata, created_by_user_id)
  VALUES
    (p_idBusiness, p_idSaleDelivery, v_eventType, v_previousStatus, p_newStatus, JSON_OBJECT('failureReason', p_failureReason, 'scheduledAt', p_scheduledAt, 'observation', p_observation), p_actorUserId);

  COMMIT;

  CALL sp_delivery_get_by_id(p_idBusiness, p_idSaleDelivery);
END$$

DELIMITER ;

/* ============================================================
   END: procedures/deliveries.sql
   ============================================================ */

/* ============================================================
   BEGIN: procedures/sales.sql
   ============================================================ */

DROP PROCEDURE IF EXISTS sp_create_sale;
DELIMITER $$

CREATE PROCEDURE sp_create_sale(
  IN p_idBusiness INT,
  IN p_idUser INT,
  IN p_sale_number VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  IN p_idempotency_key VARCHAR(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  IN p_idCustomer INT,
  IN p_idDeposit INT,
  IN p_idCashSession BIGINT,
  IN p_subtotal DECIMAL(18,2),
  IN p_discount_total DECIMAL(18,2),
  IN p_total DECIMAL(18,2),
  IN p_observation VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci
)
BEGIN
  DECLARE v_idSale INT;
  DECLARE v_cashSessionStatus VARCHAR(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
  DECLARE v_cashRegisterActive TINYINT;
  DECLARE v_existingSaleNumber VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

  DECLARE EXIT HANDLER FOR 1062
  BEGIN
    ROLLBACK;
    RESIGNAL;
  END;

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    RESIGNAL;
  END;

  IF p_sale_number IS NULL OR TRIM(p_sale_number) = '' THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'El numero de venta es obligatorio';
  END IF;

  IF p_idempotency_key IS NULL OR TRIM(p_idempotency_key) = '' THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'IDEMPOTENCY_KEY_REQUIRED';
  END IF;

  SELECT idSale, sale_number
  INTO v_idSale, v_existingSaleNumber
  FROM sales
  WHERE idBusiness = p_idBusiness
    AND idempotency_key = p_idempotency_key
  LIMIT 1;

  IF v_idSale IS NOT NULL THEN
    SELECT
      v_idSale AS idSale,
      v_existingSaleNumber AS saleNumber,
      1 AS alreadyProcessed;
  ELSE

  IF NOT EXISTS (
    SELECT 1
    FROM business_users bu
    INNER JOIN users u ON u.idUser = bu.idUser
    WHERE bu.idBusiness = p_idBusiness
      AND bu.idUser = p_idUser
      AND bu.is_active = 1
      AND u.is_active = 1
  ) THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'Usuario no autorizado para registrar ventas';
  END IF;

  IF p_idCashSession IS NULL THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'OPEN_CASH_SESSION_REQUIRED';
  END IF;

  SELECT cs.status, cr.is_active
  INTO v_cashSessionStatus, v_cashRegisterActive
  FROM cash_sessions cs
  INNER JOIN cash_registers cr
    ON cr.idCashRegister = cs.idCashRegister
    AND cr.idBusiness = cs.idBusiness
  WHERE cs.idCashSession = p_idCashSession
    AND cs.idBusiness = p_idBusiness
  LIMIT 1
  FOR UPDATE;

  IF v_cashSessionStatus IS NULL THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'OPEN_CASH_SESSION_REQUIRED';
  END IF;

  IF v_cashSessionStatus <> 'OPEN' THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'CASH_SESSION_CLOSED';
  END IF;

  IF v_cashRegisterActive = 0 THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'CASH_REGISTER_INACTIVE';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM deposits
    WHERE idDeposit = p_idDeposit
      AND idBusiness = p_idBusiness
      AND is_active = 1
  ) THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'El deposito indicado no pertenece al negocio o esta inactivo';
  END IF;

  IF p_idCustomer IS NOT NULL AND NOT EXISTS (
    SELECT 1
    FROM customers
    WHERE idCustomer = p_idCustomer
      AND idBusiness = p_idBusiness
      AND is_active = 1
  ) THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'El cliente indicado no pertenece al negocio o esta inactivo';
  END IF;

  INSERT INTO sales (
    idBusiness,
    idUser,
    sale_number,
    idempotency_key,
    idCustomer,
    idDeposit,
    idCashSession,
    sale_date,
    subtotal,
    discount_total,
    total,
    status,
    observation,
    created_at
  )
  VALUES (
    p_idBusiness,
    p_idUser,
    p_sale_number,
    p_idempotency_key,
    p_idCustomer,
    p_idDeposit,
    p_idCashSession,
    NOW(),
    p_subtotal,
    p_discount_total,
    p_total,
    'COMPLETED',
    p_observation,
    NOW()
  );

  SET v_idSale = LAST_INSERT_ID();

    SELECT v_idSale AS idSale, p_sale_number AS saleNumber, 0 AS alreadyProcessed;
  END IF;
END$$

DELIMITER ;


DROP PROCEDURE IF EXISTS sp_create_sale_detail_and_discount_stock;
DELIMITER $$

CREATE PROCEDURE sp_create_sale_detail_and_discount_stock(
  IN p_idBusiness INT,
  IN p_idUser INT,
  IN p_idSale INT,
  IN p_idProduct INT,
  IN p_idDeposit INT,
  IN p_quantity DECIMAL(18,2),
  IN p_unit_price DECIMAL(18,2),
  IN p_discount DECIMAL(18,2),
  IN p_total DECIMAL(18,2)
)
BEGIN
  DECLARE v_current_quantity DECIMAL(18,2);
  DECLARE v_unit_type VARCHAR(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
  DECLARE v_sale_number VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    RESIGNAL;
  END;

  IF NOT EXISTS (
    SELECT 1
    FROM sales
    WHERE idSale = p_idSale
      AND idBusiness = p_idBusiness
      AND status = 'COMPLETED'
  ) THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'La venta indicada no existe o no esta activa';
  END IF;

  SELECT sale_number
  INTO v_sale_number
  FROM sales
  WHERE idSale = p_idSale
    AND idBusiness = p_idBusiness
  LIMIT 1;

  IF NOT EXISTS (
    SELECT 1
    FROM products
    WHERE idProduct = p_idProduct
      AND idBusiness = p_idBusiness
      AND is_active = 1
  ) THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'El producto indicado no existe o esta inactivo';
  END IF;

  SELECT s.quantity, p.unit_type
  INTO v_current_quantity, v_unit_type
  FROM stock s
  INNER JOIN products p
    ON p.idProduct = s.idProduct
    AND p.idBusiness = s.idBusiness
  WHERE s.idBusiness = p_idBusiness
    AND s.idProduct = p_idProduct
    AND s.idDeposit = p_idDeposit
  LIMIT 1
  FOR UPDATE;

  IF p_quantity IS NULL OR p_quantity <= 0 THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'La cantidad debe ser mayor a cero';
  END IF;

  IF v_unit_type = 'UNIT' AND p_quantity <> FLOOR(p_quantity) THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'Los productos por unidad solo permiten cantidades enteras';
  END IF;

  IF v_current_quantity IS NULL OR v_current_quantity < p_quantity THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'Stock insuficiente para procesar la venta';
  END IF;

  INSERT INTO sale_details (
    idBusiness,
    idSale,
    idProduct,
    quantity,
    unit_price,
    discount_amount,
    subtotal
  )
  VALUES (
    p_idBusiness,
    p_idSale,
    p_idProduct,
    p_quantity,
    p_unit_price,
    p_discount,
    p_total
  );

  UPDATE stock
  SET
    quantity = quantity - p_quantity,
    updated_at = NOW()
  WHERE idBusiness = p_idBusiness
    AND idProduct = p_idProduct
    AND idDeposit = p_idDeposit;

  INSERT INTO stock_movements (
    idBusiness,
    idProduct,
    idUser,
    movement_type,
    idDepositFrom,
    idDepositTo,
    quantity,
    reference_type,
    reference_id,
    observation,
    created_at
  )
  VALUES (
    p_idBusiness,
    p_idProduct,
    p_idUser,
    'SALE',
    p_idDeposit,
    NULL,
    p_quantity,
    'SALE',
    p_idSale,
    CONCAT('Venta ', COALESCE(v_sale_number, CONCAT('#', p_idSale))),
    NOW()
  );

  SELECT p_idSale AS idSale;
END$$

DELIMITER ;


DROP PROCEDURE IF EXISTS sp_cancel_sale_and_revert_stock;
DELIMITER $$

CREATE PROCEDURE sp_cancel_sale_and_revert_stock(
  IN p_idSale INT,
  IN p_idBusiness INT,
  IN p_actorUserId INT
)
BEGIN
  DECLARE v_done INT DEFAULT 0;
  DECLARE v_idProduct INT;
  DECLARE v_idDeposit INT;
  DECLARE v_quantity DECIMAL(18,2);
  DECLARE v_status VARCHAR(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
  DECLARE v_cashSessionStatus VARCHAR(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
  DECLARE v_deliveryStatus VARCHAR(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
  DECLARE v_hasDelivery INT DEFAULT 0;
  DECLARE v_collectedOrConfirmedPayments INT DEFAULT 0;

  DECLARE sale_detail_cursor CURSOR FOR
    SELECT sd.idProduct, s.idDeposit, sd.quantity
    FROM sale_details sd
    INNER JOIN sales s
      ON s.idSale = sd.idSale
      AND s.idBusiness = sd.idBusiness
    WHERE sd.idSale = p_idSale
      AND sd.idBusiness = p_idBusiness;

  DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done = 1;

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    RESIGNAL;
  END;

  START TRANSACTION;

  SELECT s.status, cs.status
  INTO v_status, v_cashSessionStatus
  FROM sales s
  INNER JOIN cash_sessions cs
    ON cs.idCashSession = s.idCashSession
    AND cs.idBusiness = s.idBusiness
  WHERE s.idSale = p_idSale
    AND s.idBusiness = p_idBusiness
  LIMIT 1
  FOR UPDATE;

  IF v_status IS NULL THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'Venta no encontrada';
  END IF;

  IF v_status = 'CANCELLED' THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'La venta ya se encuentra anulada';
  END IF;

  IF v_status <> 'COMPLETED' THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'Solo se pueden anular ventas completadas';
  END IF;

  SELECT status
  INTO v_deliveryStatus
  FROM sale_deliveries
  WHERE idBusiness = p_idBusiness
    AND idSale = p_idSale
  LIMIT 1
  FOR UPDATE;

  IF v_deliveryStatus IS NOT NULL THEN
    SET v_hasDelivery = 1;
  END IF;

  IF v_hasDelivery = 0 AND v_cashSessionStatus = 'CLOSED' THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'CLOSED_CASH_SESSION_SALE_CANNOT_BE_CANCELLED';
  END IF;

  IF v_deliveryStatus IN ('OUT_FOR_DELIVERY', 'DELIVERED') THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'DELIVERY_SALE_IN_PROGRESS_CANNOT_BE_CANCELLED';
  END IF;

  SELECT COUNT(*)
  INTO v_collectedOrConfirmedPayments
  FROM sale_payments
  WHERE idBusiness = p_idBusiness
    AND idSale = p_idSale
    AND status IN ('COLLECTED', 'CONFIRMED');

  IF v_hasDelivery = 1 AND v_collectedOrConfirmedPayments > 0 THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'DELIVERY_SALE_WITH_PAYMENTS_CANNOT_BE_CANCELLED';
  END IF;

  UPDATE sales
  SET status = 'CANCELLED'
  WHERE idSale = p_idSale
    AND idBusiness = p_idBusiness;

  INSERT INTO sale_payment_events (
    idBusiness,
    idSalePayment,
    event_type,
    previous_status,
    new_status,
    metadata,
    created_by_user_id
  )
  SELECT
    p_idBusiness,
    sp.idSalePayment,
    'PAYMENT_CANCELLED',
    sp.status,
    'CANCELLED',
    JSON_OBJECT('reason', 'Venta anulada'),
    p_actorUserId
  FROM sale_payments sp
  WHERE sp.idBusiness = p_idBusiness
    AND sp.idSale = p_idSale
    AND (
      (v_hasDelivery = 1 AND sp.status = 'PENDING')
      OR (v_hasDelivery = 0 AND sp.status IN ('PENDING', 'COLLECTED', 'CONFIRMED'))
    );

  UPDATE sale_payments
  SET
    status = 'CANCELLED',
    cancelled_by_user_id = p_actorUserId,
    cancelled_at = NOW(),
    cancellation_reason = 'Venta anulada'
  WHERE idBusiness = p_idBusiness
    AND idSale = p_idSale
    AND (
      (v_hasDelivery = 1 AND status = 'PENDING')
      OR (v_hasDelivery = 0 AND status IN ('PENDING', 'COLLECTED', 'CONFIRMED'))
    );

  INSERT INTO delivery_events (
    idBusiness,
    idSaleDelivery,
    event_type,
    previous_status,
    new_status,
    metadata,
    created_by_user_id
  )
  SELECT
    p_idBusiness,
    sdv.idSaleDelivery,
    'DELIVERY_CANCELLED',
    v_deliveryStatus,
    'CANCELLED',
    JSON_OBJECT('reason', 'Venta anulada'),
    p_actorUserId
  FROM sale_deliveries sdv
  WHERE sdv.idBusiness = p_idBusiness
    AND sdv.idSale = p_idSale
    AND sdv.status IN ('PENDING', 'ASSIGNED', 'FAILED');

  UPDATE sale_deliveries
  SET
    status = 'CANCELLED',
    cancelled_at = NOW(),
    updated_at = NOW()
  WHERE idBusiness = p_idBusiness
    AND idSale = p_idSale
    AND status IN ('PENDING', 'ASSIGNED', 'FAILED');

  SET v_done = 0;

  OPEN sale_detail_cursor;

  read_loop: LOOP
    FETCH sale_detail_cursor INTO v_idProduct, v_idDeposit, v_quantity;

    IF v_done = 1 THEN
      LEAVE read_loop;
    END IF;

    INSERT INTO stock (
      idBusiness,
      idProduct,
      idDeposit,
      quantity,
      updated_at
    )
    SELECT
      p_idBusiness,
      v_idProduct,
      v_idDeposit,
      0,
      NOW()
    WHERE NOT EXISTS (
      SELECT 1
      FROM stock
      WHERE idBusiness = p_idBusiness
        AND idProduct = v_idProduct
        AND idDeposit = v_idDeposit
    );

    UPDATE stock
    SET
      quantity = quantity + v_quantity,
      updated_at = NOW()
    WHERE idBusiness = p_idBusiness
      AND idProduct = v_idProduct
      AND idDeposit = v_idDeposit;
  END LOOP;

  CLOSE sale_detail_cursor;

  COMMIT;

  CALL sp_get_sale_by_id(p_idBusiness, p_idSale);
END$$

DELIMITER ;


DROP PROCEDURE IF EXISTS sp_get_sales;
DELIMITER $$

CREATE PROCEDURE sp_get_sales(
  IN p_idBusiness INT,
  IN p_limit INT,
  IN p_offset INT,
  IN p_idDeposit INT,
  IN p_idPaymentMethod INT,
  IN p_status VARCHAR(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  IN p_saleNumberSearch VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  IN p_startDate DATETIME,
  IN p_endDate DATETIME,
  IN p_paymentStatus VARCHAR(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  IN p_deliveryStatus VARCHAR(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  IN p_settlementStatus VARCHAR(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci
)
BEGIN
  SELECT
    s.idSale,
    s.sale_number,
    s.idBusiness,
    s.idUser,
    u.name AS user_name,
    s.idCustomer,
    c.name AS customer_name,
    s.idDeposit,
    d.name AS deposit_name,
    s.idCashSession,
    MIN(sp.idPaymentMethod) AS idPaymentMethod,
    GROUP_CONCAT(DISTINCT pm.code ORDER BY pm.name SEPARATOR ', ') AS payment_method_code,
    GROUP_CONCAT(DISTINCT pm.name ORDER BY pm.name SEPARATOR ', ') AS payment_method_name,
    COALESCE(SUM(CASE WHEN sp.status = 'CONFIRMED' THEN sp.amount ELSE 0 END), 0) AS confirmed_amount,
    COALESCE(SUM(CASE WHEN sp.status = 'COLLECTED' THEN sp.amount ELSE 0 END), 0) AS collected_amount,
    COALESCE(SUM(CASE WHEN sp.status = 'PENDING' THEN sp.amount ELSE 0 END), 0) AS pending_amount,
    MAX(sdv.status) AS delivery_status,
    CASE
      WHEN COALESCE(SUM(CASE WHEN sp.status IN ('COLLECTED','CONFIRMED') THEN sp.amount ELSE 0 END), 0) = 0 THEN 'UNPAID'
      WHEN COALESCE(SUM(CASE WHEN sp.status IN ('COLLECTED','CONFIRMED') THEN sp.amount ELSE 0 END), 0) < s.total THEN 'PARTIALLY_PAID'
      ELSE 'PAID'
    END AS payment_status,
    s.sale_date,
    s.subtotal,
    s.discount_total,
    s.total,
    NULL AS payment_detail,
    s.status,
    s.observation,
    s.created_at,
    NULL AS updated_at
  FROM sales s
  INNER JOIN users u ON u.idUser = s.idUser
  INNER JOIN deposits d
    ON d.idDeposit = s.idDeposit
    AND d.idBusiness = s.idBusiness
  LEFT JOIN customers c
    ON c.idCustomer = s.idCustomer
    AND c.idBusiness = s.idBusiness
  LEFT JOIN sale_payments sp
    ON sp.idSale = s.idSale
    AND sp.idBusiness = s.idBusiness
    AND sp.status <> 'CANCELLED'
  LEFT JOIN payment_methods pm
    ON pm.idPaymentMethod = sp.idPaymentMethod
    AND pm.idBusiness = sp.idBusiness
  LEFT JOIN sale_deliveries sdv
    ON sdv.idSale = s.idSale
    AND sdv.idBusiness = s.idBusiness
  WHERE s.idBusiness = p_idBusiness
    AND (p_idDeposit IS NULL OR s.idDeposit = p_idDeposit)
    AND (
      p_idPaymentMethod IS NULL
      OR EXISTS (
        SELECT 1
        FROM sale_payments spf
        WHERE spf.idBusiness = s.idBusiness
          AND spf.idSale = s.idSale
          AND spf.idPaymentMethod = p_idPaymentMethod
          AND spf.status <> 'CANCELLED'
      )
    )
    AND (p_status IS NULL OR s.status = p_status)
    AND (
      p_deliveryStatus IS NULL
      OR p_deliveryStatus = ''
      OR (
        p_deliveryStatus = 'NO_DELIVERY'
        AND NOT EXISTS (
          SELECT 1
          FROM sale_deliveries sdf
          WHERE sdf.idBusiness = s.idBusiness
            AND sdf.idSale = s.idSale
        )
      )
      OR (
        p_deliveryStatus <> 'NO_DELIVERY'
        AND EXISTS (
          SELECT 1
          FROM sale_deliveries sdf
          WHERE sdf.idBusiness = s.idBusiness
            AND sdf.idSale = s.idSale
            AND sdf.status = p_deliveryStatus
        )
      )
    )
    AND (
      p_settlementStatus IS NULL
      OR p_settlementStatus = ''
      OR (
        p_settlementStatus = 'PENDING_SETTLEMENT'
        AND EXISTS (
          SELECT 1
          FROM sale_payments sps
          INNER JOIN payment_methods pms
            ON pms.idBusiness = sps.idBusiness
            AND pms.idPaymentMethod = sps.idPaymentMethod
          WHERE sps.idBusiness = s.idBusiness
            AND sps.idSale = s.idSale
            AND sps.status = 'COLLECTED'
            AND sps.idCashSettlement IS NULL
            AND pms.affects_cash = 1
        )
      )
      OR (
        p_settlementStatus = 'NO_PENDING_SETTLEMENT'
        AND NOT EXISTS (
          SELECT 1
          FROM sale_payments sps
          INNER JOIN payment_methods pms
            ON pms.idBusiness = sps.idBusiness
            AND pms.idPaymentMethod = sps.idPaymentMethod
          WHERE sps.idBusiness = s.idBusiness
            AND sps.idSale = s.idSale
            AND sps.status = 'COLLECTED'
            AND sps.idCashSettlement IS NULL
            AND pms.affects_cash = 1
        )
      )
    )
    AND (
      p_saleNumberSearch IS NULL
      OR p_saleNumberSearch = ''
      OR s.sale_number COLLATE utf8mb4_unicode_ci LIKE CONCAT('%', p_saleNumberSearch COLLATE utf8mb4_unicode_ci, '%')
    )
    AND (p_startDate IS NULL OR s.sale_date >= p_startDate)
    AND (p_endDate IS NULL OR s.sale_date <= p_endDate)
  GROUP BY
    s.idSale,
    s.sale_number,
    s.idBusiness,
    s.idUser,
    u.name,
    s.idCustomer,
    c.name,
    s.idDeposit,
    d.name,
    s.idCashSession,
    s.sale_date,
    s.subtotal,
    s.discount_total,
    s.total,
    s.status,
    s.observation,
    s.created_at
  HAVING (
    p_paymentStatus IS NULL
    OR p_paymentStatus = ''
    OR CASE
      WHEN COALESCE(SUM(CASE WHEN sp.status IN ('COLLECTED','CONFIRMED') THEN sp.amount ELSE 0 END), 0) = 0 THEN 'UNPAID'
      WHEN COALESCE(SUM(CASE WHEN sp.status IN ('COLLECTED','CONFIRMED') THEN sp.amount ELSE 0 END), 0) < s.total THEN 'PARTIALLY_PAID'
      ELSE 'PAID'
    END = p_paymentStatus
  )
  ORDER BY s.created_at DESC, s.idSale DESC
  LIMIT p_limit OFFSET p_offset;

  SELECT
    COUNT(*) AS totalRecords,
    SUM(CASE WHEN filtered_sales.status = 'COMPLETED' THEN 1 ELSE 0 END) AS completedRecords,
    SUM(CASE WHEN filtered_sales.status = 'CANCELLED' THEN 1 ELSE 0 END) AS cancelledRecords,
    COALESCE(SUM(CASE WHEN filtered_sales.status = 'COMPLETED' THEN filtered_sales.total ELSE 0 END), 0) AS completedTotal
  FROM (
    SELECT
      s.idSale,
      s.status,
      s.total,
      CASE
        WHEN COALESCE(SUM(CASE WHEN sp.status IN ('COLLECTED','CONFIRMED') THEN sp.amount ELSE 0 END), 0) = 0 THEN 'UNPAID'
        WHEN COALESCE(SUM(CASE WHEN sp.status IN ('COLLECTED','CONFIRMED') THEN sp.amount ELSE 0 END), 0) < s.total THEN 'PARTIALLY_PAID'
        ELSE 'PAID'
      END AS payment_status
    FROM sales s
    LEFT JOIN sale_payments sp
      ON sp.idSale = s.idSale
      AND sp.idBusiness = s.idBusiness
      AND sp.status <> 'CANCELLED'
    WHERE s.idBusiness = p_idBusiness
      AND (p_idDeposit IS NULL OR s.idDeposit = p_idDeposit)
      AND (
        p_idPaymentMethod IS NULL
        OR EXISTS (
          SELECT 1
          FROM sale_payments spf
          WHERE spf.idBusiness = s.idBusiness
            AND spf.idSale = s.idSale
            AND spf.idPaymentMethod = p_idPaymentMethod
            AND spf.status <> 'CANCELLED'
        )
      )
      AND (p_status IS NULL OR s.status = p_status)
      AND (
        p_deliveryStatus IS NULL
        OR p_deliveryStatus = ''
        OR (
          p_deliveryStatus = 'NO_DELIVERY'
          AND NOT EXISTS (
            SELECT 1
            FROM sale_deliveries sdf
            WHERE sdf.idBusiness = s.idBusiness
              AND sdf.idSale = s.idSale
          )
        )
        OR (
          p_deliveryStatus <> 'NO_DELIVERY'
          AND EXISTS (
            SELECT 1
            FROM sale_deliveries sdf
            WHERE sdf.idBusiness = s.idBusiness
              AND sdf.idSale = s.idSale
              AND sdf.status = p_deliveryStatus
          )
        )
      )
      AND (
        p_settlementStatus IS NULL
        OR p_settlementStatus = ''
        OR (
          p_settlementStatus = 'PENDING_SETTLEMENT'
          AND EXISTS (
            SELECT 1
            FROM sale_payments sps
            INNER JOIN payment_methods pms
              ON pms.idBusiness = sps.idBusiness
              AND pms.idPaymentMethod = sps.idPaymentMethod
            WHERE sps.idBusiness = s.idBusiness
              AND sps.idSale = s.idSale
              AND sps.status = 'COLLECTED'
              AND sps.idCashSettlement IS NULL
              AND pms.affects_cash = 1
          )
        )
        OR (
          p_settlementStatus = 'NO_PENDING_SETTLEMENT'
          AND NOT EXISTS (
            SELECT 1
            FROM sale_payments sps
            INNER JOIN payment_methods pms
              ON pms.idBusiness = sps.idBusiness
              AND pms.idPaymentMethod = sps.idPaymentMethod
            WHERE sps.idBusiness = s.idBusiness
              AND sps.idSale = s.idSale
              AND sps.status = 'COLLECTED'
              AND sps.idCashSettlement IS NULL
              AND pms.affects_cash = 1
          )
        )
      )
      AND (
        p_saleNumberSearch IS NULL
        OR p_saleNumberSearch = ''
        OR s.sale_number COLLATE utf8mb4_unicode_ci LIKE CONCAT('%', p_saleNumberSearch COLLATE utf8mb4_unicode_ci, '%')
      )
      AND (p_startDate IS NULL OR s.sale_date >= p_startDate)
      AND (p_endDate IS NULL OR s.sale_date <= p_endDate)
    GROUP BY
      s.idSale,
      s.status,
      s.total
    HAVING (
      p_paymentStatus IS NULL
      OR p_paymentStatus = ''
      OR payment_status = p_paymentStatus
    )
  ) filtered_sales;
END$$

DELIMITER ;


DROP PROCEDURE IF EXISTS sp_get_sale_by_id;
DELIMITER $$

CREATE PROCEDURE sp_get_sale_by_id(
  IN p_idBusiness INT,
  IN p_idSale INT
)
BEGIN
  SELECT
    s.idSale,
    s.sale_number,
    s.idBusiness,
    s.idUser,
    u.name AS user_name,
    s.idCustomer,
    c.name AS customer_name,
    s.idDeposit,
    d.name AS deposit_name,
    s.idCashSession,
    MIN(sp.idPaymentMethod) AS idPaymentMethod,
    GROUP_CONCAT(DISTINCT pm.code ORDER BY pm.name SEPARATOR ', ') AS payment_method_code,
    GROUP_CONCAT(DISTINCT pm.name ORDER BY pm.name SEPARATOR ', ') AS payment_method_name,
    COALESCE(SUM(CASE WHEN sp.status = 'CONFIRMED' THEN sp.amount ELSE 0 END), 0) AS confirmed_amount,
    COALESCE(SUM(CASE WHEN sp.status = 'COLLECTED' THEN sp.amount ELSE 0 END), 0) AS collected_amount,
    COALESCE(SUM(CASE WHEN sp.status = 'PENDING' THEN sp.amount ELSE 0 END), 0) AS pending_amount,
    MAX(sdv.status) AS delivery_status,
    CASE
      WHEN COALESCE(SUM(CASE WHEN sp.status IN ('COLLECTED','CONFIRMED') THEN sp.amount ELSE 0 END), 0) = 0 THEN 'UNPAID'
      WHEN COALESCE(SUM(CASE WHEN sp.status IN ('COLLECTED','CONFIRMED') THEN sp.amount ELSE 0 END), 0) < s.total THEN 'PARTIALLY_PAID'
      ELSE 'PAID'
    END AS payment_status,
    s.sale_date,
    s.subtotal,
    s.discount_total,
    s.total,
    NULL AS payment_detail,
    s.status,
    s.observation,
    s.created_at,
    NULL AS updated_at
  FROM sales s
  INNER JOIN users u ON u.idUser = s.idUser
  INNER JOIN deposits d
    ON d.idDeposit = s.idDeposit
    AND d.idBusiness = s.idBusiness
  LEFT JOIN customers c
    ON c.idCustomer = s.idCustomer
    AND c.idBusiness = s.idBusiness
  LEFT JOIN sale_payments sp
    ON sp.idSale = s.idSale
    AND sp.idBusiness = s.idBusiness
    AND sp.status <> 'CANCELLED'
  LEFT JOIN payment_methods pm
    ON pm.idPaymentMethod = sp.idPaymentMethod
    AND pm.idBusiness = sp.idBusiness
  LEFT JOIN sale_deliveries sdv
    ON sdv.idSale = s.idSale
    AND sdv.idBusiness = s.idBusiness
  WHERE s.idBusiness = p_idBusiness
    AND s.idSale = p_idSale
  GROUP BY
    s.idSale,
    s.sale_number,
    s.idBusiness,
    s.idUser,
    u.name,
    s.idCustomer,
    c.name,
    s.idDeposit,
    d.name,
    s.idCashSession,
    s.sale_date,
    s.subtotal,
    s.discount_total,
    s.total,
    s.status,
    s.observation,
    s.created_at
  LIMIT 1;

  SELECT
    sd.idSaleDetail,
    sd.idSale,
    sd.idBusiness,
    sd.idProduct,
    p.name AS product_name,
    p.barcode,
    p.image_url AS product_image_url,
    s.idDeposit,
    d.name AS deposit_name,
    sd.quantity,
    sd.unit_price,
    sd.discount_amount AS discount,
    sd.subtotal AS total,
    s.created_at
  FROM sale_details sd
  INNER JOIN sales s
    ON s.idSale = sd.idSale
    AND s.idBusiness = sd.idBusiness
  INNER JOIN products p
    ON p.idProduct = sd.idProduct
    AND p.idBusiness = sd.idBusiness
  INNER JOIN deposits d
    ON d.idDeposit = s.idDeposit
    AND d.idBusiness = sd.idBusiness
  WHERE sd.idBusiness = p_idBusiness
    AND sd.idSale = p_idSale
  ORDER BY sd.idSaleDetail ASC;

  SELECT
    sp.idSalePayment,
    sp.idBusiness,
    sp.idSale,
    sp.idPaymentMethod,
    pm.code AS payment_method_code,
    pm.name AS payment_method_name,
    pm.affects_cash,
    sp.amount,
    sp.status,
    sp.idCashSession,
    sp.idCashSettlement,
    sp.reference,
    sp.observation,
    sp.created_at,
    sp.collected_at,
    sp.confirmed_at,
    sp.cancelled_at
  FROM sale_payments sp
  INNER JOIN payment_methods pm
    ON pm.idPaymentMethod = sp.idPaymentMethod
    AND pm.idBusiness = sp.idBusiness
  WHERE sp.idBusiness = p_idBusiness
    AND sp.idSale = p_idSale
  ORDER BY sp.idSalePayment ASC;

  SELECT
    sdv.idSaleDelivery,
    sdv.idBusiness,
    sdv.idSale,
    sdv.assigned_to_user_id,
    assigned_user.name AS assigned_user_name,
    sdv.status,
    sdv.recipient_name,
    sdv.recipient_phone,
    sdv.delivery_address,
    sdv.delivery_reference,
    sdv.scheduled_at,
    sdv.assigned_at,
    sdv.out_for_delivery_at,
    sdv.delivered_at,
    sdv.failed_at,
    sdv.cancelled_at,
    sdv.failure_reason,
    sdv.observation,
    sdv.created_at,
    sdv.updated_at
  FROM sale_deliveries sdv
  LEFT JOIN users assigned_user ON assigned_user.idUser = sdv.assigned_to_user_id
  WHERE sdv.idBusiness = p_idBusiness
    AND sdv.idSale = p_idSale
  LIMIT 1;
END$$

DELIMITER ;


DROP PROCEDURE IF EXISTS sp_get_products_with_stock_by_deposit;
DELIMITER $$

CREATE PROCEDURE sp_get_products_with_stock_by_deposit(
  IN p_idBusiness INT,
  IN p_idDeposit INT
)
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM deposits
    WHERE idDeposit = p_idDeposit
      AND idBusiness = p_idBusiness
      AND is_active = 1
  ) THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'El deposito indicado no pertenece al negocio o esta inactivo';
  END IF;

  SELECT
    p.idProduct,
    p.idBusiness,
    p.idProductCategory,
    pc.name AS category_name,
    p.barcode,
    p.name,
    p.description,
    p.image_url,
    p.price_cost,
    p.price_sale,
    p.price_wholesale,
    p.unit_type,
    p.stock_min,
    p.is_active,
    COALESCE(s.quantity, 0) AS stock_quantity
  FROM products p
  LEFT JOIN product_categories pc
    ON pc.idProductCategory = p.idProductCategory
    AND pc.idBusiness = p.idBusiness
  LEFT JOIN stock s
    ON s.idBusiness = p.idBusiness
    AND s.idProduct = p.idProduct
    AND s.idDeposit = p_idDeposit
  WHERE p.idBusiness = p_idBusiness
    AND p.is_active = 1
    AND COALESCE(s.quantity, 0) > 0
  ORDER BY p.name ASC;
END$$

DELIMITER ;

/* ============================================================
   END: procedures/sales.sql
   ============================================================ */

